import { metricLabel } from '../../data/ecology'
import { qianlingSources, type KnowledgeSourceId } from '../../data/qianling-knowledge'
import type { GuidePageContext, GuideRoute } from './MascotGuideController'

export interface GuideMessage {
  eyebrow: string
  title: string
  text: string
  action?: { label: string; href?: string; targetId?: string }
  sourceIds?: KnowledgeSourceId[]
}

export const storyGuideMessages: GuideMessage[] = [
  { eyebrow: 'ACT 01 · AIR', title: '先确认时间与单位', text: '这一幕展示城市月度空气浓度。数值描述特定月份，不等同于一座城市的长期生态水平。' },
  { eyebrow: 'ACT 02 · WATER', title: '水质依附于监测断面', text: '同为“优良比例”，监测断面范围不同也不能直接计算增减。先看清范围，再读百分比。' },
  { eyebrow: 'ACT 03 · FOREST', title: '森林是栖息地的基础', text: '连续、质量良好并彼此连通的森林，为野生动物提供食物与迁移空间；营造林面积不能直接推断黔金丝猴种群增长。' },
  { eyebrow: 'EPILOGUE · EVIDENCE', title: '让证据留下，而不是预设结论', text: '改善、保持、上升或缺失都应如实呈现。保护生态，也包括尊重数据能够说明的边界。' },
]

export function buildGuideMessage(route: GuideRoute, context: GuidePageContext): GuideMessage {
  if (route === 'atlas' && context.route === 'atlas') {
    if (context.city === '铜仁市') return {
      eyebrow: 'FANJINGSHAN · HABITAT',
      title: '铜仁不是一整片“分布区”',
      text: '梵净山位于铜仁区域，黔金丝猴的全球野外分布集中在梵净山保护地体系及其连通生境。本图只选择城市空气数据，不能据此绘制物种分布边界。',
      sourceIds: ['guizhou-plan', 'unesco-fanjingshan'],
    }
    return {
      eyebrow: 'CITY SIGNAL · LIVE',
      title: `正在读取${context.city.replace('市', '')}`,
      text: `${metricLabel[context.metric]}为${context.value} μg/m³。你可以选择铜仁，再由我介绍梵净山与黔金丝猴栖息地。`,
    }
  }

  if (route === 'time' && context.route === 'time') {
    const prefix = `${context.periodLabel}${context.city}${metricLabel[context.metric]}为${context.value ?? '暂无数据'} μg/m³。`
    if (context.value === null || context.baselineValue === undefined || !context.baselineLabel) return {
      eyebrow: 'TIME NODE · VERIFIED',
      title: '没有同月基准，就不生成趋势',
      text: `${prefix}当前数据集中没有更早的同月节点，因此我不会把季节差异包装成升降结论。`,
    }
    const delta = context.value - context.baselineValue
    const direction = delta === 0 ? '持平' : delta < 0 ? `低${Math.abs(delta)}` : `高${Math.abs(delta)}`
    return {
      eyebrow: 'TIME NODE · VERIFIED',
      title: `${context.city.replace('市', '')} · ${metricLabel[context.metric]}同月对照`,
      text: `${prefix}与${context.baselineLabel}同口径数值${context.baselineValue} μg/m³相比，${delta === 0 ? '数值持平' : `当前数值${direction} μg/m³`}。这只描述两个真实月度节点。`,
      action: { label: '查看双时刻对照镜', targetId: 'time-comparator' },
    }
  }

  if (route === 'symbiosis' && context.route === 'symbiosis') {
    return context.section === 'water'
      ? { eyebrow: 'WATER ARCHIVE', title: '沿着监测范围读水质', text: '先确认指标对应的是哪些河流或断面。不同断面范围的数据可以并列理解，但不能直接计算趋势。' }
      : { eyebrow: 'FOREST ARCHIVE', title: '森林数量不等于栖息地质量', text: '营造林面积记录年度行动；森林覆盖率、林分质量和生态连通性还需要独立证据，不能直接推断黔金丝猴种群变化。' }
  }

  if (route === 'story' && context.route === 'story') return storyGuideMessages[Math.max(0, Math.min(storyGuideMessages.length - 1, context.act))]

  if (route === 'prologue' && context.route === 'prologue') {
    if (context.theme === 'water') return {
      eyebrow: 'TRIAD SIGNAL · WATER',
      title: '水的蓝光是艺术信号',
      text: '当前证据记录的是省级年度出境断面水质优良比例，不代表所有河流的实时状态。进入专题后，可以继续核对监测范围。',
      action: { label: '探索江河生态', href: '#/symbiosis?section=water' },
    }
    if (context.theme === 'forest') return {
      eyebrow: 'TRIAD SIGNAL · FOREST',
      title: '营造林面积是年度行动记录',
      text: '它不能替代森林覆盖率、林分质量或栖息地连通性，也不能直接推断黔金丝猴种群变化。',
      action: { label: '探索森林生态', href: '#/symbiosis?section=forest' },
    }
    if (context.theme === 'air') return {
      eyebrow: 'TRIAD SIGNAL · AIR',
      title: '从城市月度切片开始',
      text: '空气信号对应贵州9个中心城市的月度PM2.5平均浓度。进入图谱后，可以逐城查看真实监测值。',
      action: { label: '进入城市空气监测', href: '#/atlas' },
    }
    return {
      eyebrow: 'QIANLING · ECO GUIDE',
      title: '你好，我是黔小灵！',
      text: '欢迎进入三域生态生命舱。空气、水和森林使用不同的统计尺度；场景可以诗意，结论必须来自证据。',
      action: { label: '启动生态探索', targetId: 'triad-evidence' },
    }
  }

  return { eyebrow: 'QIANLING · ECO GUIDE', title: '一起读懂生态数据', text: '点击下方问题卡片，或在页面中选择真实数据节点，我会给出对应提示。' }
}

export const resolveMessageSources = (message: GuideMessage) => (message.sourceIds ?? []).map((id) => qianlingSources[id])
