import { useEffect, useMemo, useRef, useState, type CSSProperties } from 'react'
import type { AirMetric, AnnualAirPeriod, CityKey } from '../data/ecology'
import { getSource, metricLabel } from '../data/ecology'
import { getCityGeo, guizhouTerrain } from '../data/guizhouGeo'
import { loadGuizhouDem, type GuizhouDemGrid } from './guizhouTerrainMath'

const MAP_WIDTH = 720
const MAP_HEIGHT = 540
const YEARS = Array.from({ length: 10 }, (_, index) => 2016 + index)

type CityValueRecord = {
  city: CityKey
  pm25: number | null
  pm10: number | null
}

interface TemporalCityExplorerProps {
  records: CityValueRecord[]
  periods: AnnualAirPeriod[]
  metric: AirMetric
  selected: CityKey
  selectedYear: number
  periodLabel: string
  onSelectCity: (city: CityKey) => void
  onSelectYear: (year: number) => void
}

function terrainColor(elevation: number, shade: number) {
  const stops = [
    { at: 0, color: [8, 37, 28] },
    { at: 0.32, color: [17, 76, 52] },
    { at: 0.68, color: [37, 112, 75] },
    { at: 1, color: [99, 143, 101] },
  ]
  const upperIndex = stops.findIndex((stop) => stop.at >= elevation)
  const upper = stops[Math.max(1, upperIndex)]
  const lower = stops[Math.max(0, upperIndex - 1)]
  const amount = Math.max(0, Math.min(1, (elevation - lower.at) / (upper.at - lower.at)))
  return lower.color.map((value, index) => Math.round((value + (upper.color[index] - value) * amount) * shade))
}

function drawRelief(canvas: HTMLCanvasElement, grid: GuizhouDemGrid) {
  const context = canvas.getContext('2d')
  if (!context) return
  canvas.width = grid.width
  canvas.height = grid.height
  const image = context.createImageData(grid.width, grid.height)
  const span = Math.max(1, grid.maximum - grid.minimum)

  for (let y = 0; y < grid.height; y += 1) {
    for (let x = 0; x < grid.width; x += 1) {
      const index = y * grid.width + x
      const encoded = grid.values[index]
      if (encoded === 65535) continue
      const elevation = grid.minimum + encoded / 65534 * span
      const left = grid.values[y * grid.width + Math.max(0, x - 1)]
      const right = grid.values[y * grid.width + Math.min(grid.width - 1, x + 1)]
      const up = grid.values[Math.max(0, y - 1) * grid.width + x]
      const down = grid.values[Math.min(grid.height - 1, y + 1) * grid.width + x]
      const safeElevation = (sample: number) => sample === 65535 ? elevation : grid.minimum + sample / 65534 * span
      const dx = safeElevation(right) - safeElevation(left)
      const dy = safeElevation(down) - safeElevation(up)
      const shade = Math.max(0.52, Math.min(1.18, 0.86 - (dx - dy) / 850))
      const color = terrainColor((elevation - grid.minimum) / span, shade)
      const pixel = index * 4
      image.data[pixel] = color[0]
      image.data[pixel + 1] = color[1]
      image.data[pixel + 2] = color[2]
      image.data[pixel + 3] = 255
    }
  }
  context.putImageData(image, 0, 0)

  // Derive contour lines from the same DEM samples; never use air values as a surface.
  context.lineWidth = 0.65
  for (let level = Math.ceil(grid.minimum / 300) * 300; level <= grid.maximum; level += 300) {
    context.beginPath()
    context.strokeStyle = level % 900 === 0 ? 'rgba(203,255,56,.36)' : 'rgba(147,205,169,.19)'
    for (let y = 0; y < grid.height - 1; y += 1) {
      for (let x = 0; x < grid.width - 1; x += 1) {
        const i = y * grid.width + x
        const corners = [grid.values[i], grid.values[i + 1], grid.values[i + grid.width + 1], grid.values[i + grid.width]]
        if (corners.some((value) => value === 65535)) continue
        const heights = corners.map((value) => grid.minimum + value / 65534 * span)
        const edges: Array<[number, number]> = []
        const edgePairs: Array<[number, number]> = [[0, 1], [1, 2], [3, 2], [0, 3]]
        for (const [a, b] of edgePairs) {
          const ha = heights[a]
          const hb = heights[b]
          if ((ha < level && hb >= level) || (ha >= level && hb < level)) {
            const t = (level - ha) / (hb - ha)
            const positions: Array<[number, number]> = [[0, 0], [1, 0], [1, 1], [0, 1]]
            const [ax, ay] = positions[a]
            const [bx, by] = positions[b]
            edges.push([x + ax + (bx - ax) * t, y + ay + (by - ay) * t])
          }
        }
        if (edges.length === 2) {
          context.moveTo(edges[0][0], edges[0][1])
          context.lineTo(edges[1][0], edges[1][1])
        } else if (edges.length === 4) {
          context.moveTo(edges[0][0], edges[0][1])
          context.lineTo(edges[1][0], edges[1][1])
          context.moveTo(edges[2][0], edges[2][1])
          context.lineTo(edges[3][0], edges[3][1])
        }
      }
    }
    context.stroke()
  }
}

function project(longitude: number, latitude: number) {
  const { bounds } = guizhouTerrain
  return {
    x: (longitude - bounds.minLon) / (bounds.maxLon - bounds.minLon) * MAP_WIDTH,
    y: (bounds.maxLat - latitude) / (bounds.maxLat - bounds.minLat) * MAP_HEIGHT,
  }
}

function pointColor(value: number | null, metric: AirMetric, records: CityValueRecord[]) {
  if (value === null) return '#71827a'
  const values = records.map((record) => record[metric]).filter((item): item is number => item !== null)
  const low = Math.min(...values)
  const high = Math.max(...values)
  const position = (value - low) / Math.max(1, high - low)
  const stops = [
    { at: 0, color: [105, 214, 197] },
    { at: 0.5, color: [203, 255, 56] },
    { at: 1, color: [255, 140, 58] },
  ]
  const upperIndex = stops.findIndex((stop) => stop.at >= position)
  const upper = stops[Math.max(1, upperIndex)]
  const lower = stops[Math.max(0, upperIndex - 1)]
  const amount = (position - lower.at) / (upper.at - lower.at)
  return `#${lower.color.map((channel, index) => Math.round(channel + (upper.color[index] - channel) * amount).toString(16).padStart(2, '0')).join('')}`
}

function buildTrend(periods: AnnualAirPeriod[], city: CityKey, metric: AirMetric) {
  const values = YEARS.map((year) => {
    const record = periods.find((period) => period.year === year)?.records.find((item) => item.city === city)
    return record?.[metric] ?? null
  })
  const axisMax = metric === 'pm25' ? 50 : 100
  const left = 52
  const right = 680
  const top = 34
  const bottom = 232
  const points = values.map((value, index) => value === null ? null : ({
    year: YEARS[index],
    value,
    x: left + index / (YEARS.length - 1) * (right - left),
    y: bottom - value / axisMax * (bottom - top),
  }))
  const segments: Array<Array<NonNullable<(typeof points)[number]>>> = []
  let segment: Array<NonNullable<(typeof points)[number]>> = []
  points.forEach((point) => {
    if (point) segment.push(point)
    else if (segment.length) {
      segments.push(segment)
      segment = []
    }
  })
  if (segment.length) segments.push(segment)
  return { points, segments, axisMax }
}

export function TemporalCityExplorer({ records, periods, metric, selected, selectedYear, periodLabel, onSelectCity, onSelectYear }: TemporalCityExplorerProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [terrainStatus, setTerrainStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const trend = useMemo(() => buildTrend(periods, selected, metric), [periods, selected, metric])
  const cityValues = records.map((record) => record[metric]).filter((value): value is number => value !== null)
  const valueRange = cityValues.length ? [Math.min(...cityValues), Math.max(...cityValues)] as const : null
  const selectedPoint = trend.points.find((point) => point?.year === selectedYear) ?? null
  const selectedValue = selectedPoint?.value ?? null
  const selectedSource = periods.find((period) => period.year === selectedYear)?.sourceIds
    .map((sourceId) => getSource(sourceId)?.title)
    .filter((title): title is string => Boolean(title))[0]
  const boundaryPath = useMemo(() => guizhouTerrain.boundary.map(([longitude, latitude], index) => {
    const point = project(longitude, latitude)
    return `${index === 0 ? 'M' : 'L'}${point.x.toFixed(1)},${point.y.toFixed(1)}`
  }).join(' ') + ' Z', [])

  useEffect(() => {
    const controller = new AbortController()
    loadGuizhouDem(controller.signal)
      .then((grid) => {
        if (!canvasRef.current) return
        drawRelief(canvasRef.current, grid)
        setTerrainStatus('ready')
      })
      .catch(() => {
        if (!controller.signal.aborted) setTerrainStatus('error')
      })
    return () => controller.abort()
  }, [])

  return (
    <section className="temporal-city-explorer" aria-label="九城空间与城市历史趋势联动分析" data-guide-target="time-comparison">
      <div className="temporal-gis-panel">
        <header className="temporal-explorer-heading">
          <div><span>GIS / GUIZHOU · WGS84</span><h2>贵州九城空间监测</h2><p>地形晕渲 · 城市监测节点</p></div>
          <div className="temporal-map-legend"><span>{valueRange?.[0] ?? '—'}</span><i /><span>{valueRange?.[1] ?? '—'}</span><small>{metricLabel[metric]} · μg/m³ · 当前年份九城范围</small></div>
        </header>
        <div className={`temporal-gis-map terrain-${terrainStatus}`}>
          <canvas ref={canvasRef} aria-hidden="true" />
          <svg viewBox={`0 0 ${MAP_WIDTH} ${MAP_HEIGHT}`} role="img" aria-label={`${periodLabel}${metricLabel[metric]}贵州九城地理定位；地形颜色表示DEM高程，污染数值仅映射至城市监测点`}>
            <defs>
              <clipPath id="temporal-guizhou-boundary"><path d={boundaryPath} /></clipPath>
              <pattern id="temporal-map-grid" width="72" height="72" patternUnits="userSpaceOnUse"><path d="M72 0H0V72" fill="none" stroke="rgba(196,220,199,.13)" strokeWidth=".7" strokeDasharray="2 4" /></pattern>
            </defs>
            <rect width={MAP_WIDTH} height={MAP_HEIGHT} fill="url(#temporal-map-grid)" clipPath="url(#temporal-guizhou-boundary)" />
            <path className="temporal-guizhou-outline" d={boundaryPath} />
            {guizhouTerrain.boundary.filter((_, index) => index % 80 === 0).map(([longitude, latitude], index) => {
              const point = project(longitude, latitude)
              return <circle key={index} className="temporal-boundary-tick" cx={point.x} cy={point.y} r="1.4" />
            })}
            {records.map((record) => {
              const geo = getCityGeo(record.city)
              const position = project(geo.longitude, geo.latitude)
              const labelX = position.x + (geo.labelOffset[0] >= 0 ? 18 : -112)
              const labelY = position.y - geo.labelOffset[1] * MAP_HEIGHT / (guizhouTerrain.bounds.maxLat - guizhouTerrain.bounds.minLat) - 9
              const value = record[metric]
              const color = pointColor(value, metric, records)
              const isSelected = record.city === selected
              return (
                <g
                  key={record.city}
                  className={`temporal-gis-city ${isSelected ? 'is-selected' : ''}`}
                  role="button"
                  tabIndex={0}
                  style={{ '--pin-color': color } as CSSProperties}
                  aria-label={`${record.city}，${periodLabel}${metricLabel[metric]}${value === null ? '暂无数据' : `${value}微克每立方米`}`}
                  onClick={() => onSelectCity(record.city)}
                  onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onSelectCity(record.city) } }}
                >
                  <line x1={position.x} y1={position.y} x2={labelX + (geo.labelOffset[0] >= 0 ? 0 : 108)} y2={labelY + 8} />
                  <circle className="gis-pin-halo" cx={position.x} cy={position.y} r={isSelected ? 12 : 8} />
                  <circle className="gis-pin-ring" cx={position.x} cy={position.y} r="5.4" />
                  <circle className="gis-pin-core" cx={position.x} cy={position.y} r="1.7" />
                  <g transform={`translate(${labelX},${labelY})`}>
                    <rect width="108" height="19" rx="1" />
                    <text x="6" y="12.7" className="gis-city-label">{record.city.replace('市', '')}</text>
                    <text x="102" y="12.7" textAnchor="end" className="gis-city-value">{value ?? '—'}</text>
                  </g>
                </g>
              )
            })}
            <text className="gis-coordinate" x="8" y="18">29.22°N</text><text className="gis-coordinate" x="8" y="530">24.60°N</text>
            <text className="gis-coordinate" x="8" y="516">103.60°E</text><text className="gis-coordinate" x="648" y="516">109.60°E</text>
          </svg>
          {terrainStatus === 'loading' && <div className="temporal-map-state">正在载入贵州 DEM 地形</div>}
          {terrainStatus === 'error' && <div className="temporal-map-state is-error">地形数据暂不可用；城市坐标与数值仍可查看</div>}
          <div className="temporal-map-scale"><span>N</span><i /><small>WGS84 · EPSG:4326</small></div>
        </div>
        <footer className="temporal-map-foot"><span>{periodLabel} · {metricLabel[metric]} 城市值</span><small>颜色仅表示DEM高程；生态数值仅标注于城市点</small></footer>
      </div>

      <div className="temporal-trend-panel">
        <header className="temporal-explorer-heading trend-heading">
          <div><span>CITY TEMPORAL TREND / 已核验年度序列</span><h2>城市时间轨迹</h2><p>点击地图切换城市 · 点击有效节点跳转年份</p></div>
          <span className="trend-metric">{metricLabel[metric]} · μg/m³</span>
        </header>
        <div className="temporal-trend-summary">
          <div><small>SELECTED CITY</small><strong>{selected.replace('市', '')}</strong></div>
          <div><small>SELECTED YEAR</small><strong>{selectedYear}</strong></div>
          <div><small>ANNUAL VERIFIED VALUE</small><strong>{selectedValue ?? '—'}<i>μg/m³</i></strong></div>
        </div>
        <div className="temporal-history-chart">
          <svg viewBox="0 0 720 290" role="img" aria-label={`${selected}${metricLabel[metric]}2016至2025年已核验城市年度变化，缺失年份断开`}>
            {[0, .25, .5, .75, 1].map((step) => {
              const y = 232 - step * 198
              return <g key={step}><line className="trend-gridline" x1="52" x2="680" y1={y} y2={y} /><text className="trend-axis-label" x="42" y={y + 3} textAnchor="end">{Math.round(trend.axisMax * step)}</text></g>
            })}
            {trend.segments.filter((segment) => segment.length > 1).map((segment, index) => <polyline key={index} className="trend-line-segment" points={segment.map((point) => `${point.x},${point.y}`).join(' ')} />)}
            {trend.points.map((point, index) => {
              const x = 52 + index / (YEARS.length - 1) * 628
              if (!point) return <g key={YEARS[index]} className="trend-missing-node"><circle cx={x} cy="232" r="3.2" /><text x={x} y="216" textAnchor="middle">缺</text><text className="trend-year-label" x={x} y="257" textAnchor="middle">{YEARS[index]}</text></g>
              const active = point.year === selectedYear
              return <g key={point.year} className={`trend-data-node ${active ? 'is-active' : ''}`} role="button" tabIndex={0} aria-label={`${point.year}年${selected.replace('市', '')}${metricLabel[metric]}${point.value}微克每立方米，已核实`} onClick={() => onSelectYear(point.year)} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onSelectYear(point.year) } }}>
                <circle className="trend-point-halo" cx={point.x} cy={point.y} r={active ? 10 : 7} />
                <circle className="trend-point" cx={point.x} cy={point.y} r={active ? 4.3 : 3.2} />
                <text className="trend-value-label" x={point.x} y={point.y - 11} textAnchor="middle">{point.value}</text>
                <text className="trend-year-label" x={point.x} y="257" textAnchor="middle">{point.year}</text>
              </g>
            })}
          </svg>
          <div className="temporal-trend-legend"><span><i className="is-verified" />已核验数值</span><span><i className="is-missing" />暂无逐城核验值</span><span>缺失年份不连线</span></div>
        </div>
        <footer className="temporal-trend-foot"><span>{selected} · 年度均值 · {metricLabel[metric]}</span><small>数据来源：{selectedSource ?? '贵州省生态环境状况公报'}</small></footer>
      </div>
    </section>
  )
}
