import { useEffect, useMemo, useRef, useState } from 'react'
import { AirArchiveMatrix, AirBars, MetricToggle } from '../components/AirVisuals'
import { SourcePanel } from '../components/SourcePanel'
import { ContourField } from '../components/ContourField'
import { HistoricalSignalTrace, MicroDataSpectrum } from '../components/EcoHudCharts'
import { LazyGuizhouTerrain3D } from '../components/LazyGuizhouTerrain3D'
import {
  airPeriods,
  annualAirPeriods,
  compareAir,
  compareAnnualAir,
  getAverage,
  getComparableAnnualAirPeriods,
  metricLabel,
  toRenderableAirPeriod,
  type AirMetric,
  type CityKey,
} from '../data/ecology'
import { getCityGeo, guizhouCities, guizhouGeoSources, guizhouTerrain } from '../data/guizhouGeo'
import { useMascotGuideController } from '../components/qianling/MascotGuideController'

export function Atlas() {
  const [metric, setMetric] = useState<AirMetric>('pm25')
  const [timeMode, setTimeMode] = useState<'annual' | 'monthly'>('annual')
  const [annualYear, setAnnualYear] = useState(2024)
  const [selected, setSelected] = useState<CityKey>('贵阳市')
  const [scanning, setScanning] = useState(false)
  const [focusSignal, setFocusSignal] = useState(0)
  const [resetViewSignal, setResetViewSignal] = useState(0)
  const [historyOpen, setHistoryOpen] = useState(false)
  const { publishPageContext } = useMascotGuideController()
  const previousSelected = useRef<CityKey>(selected)
  const scanTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const comparableAnnual = useMemo(() => getComparableAnnualAirPeriods(metric), [metric])
  const annualPeriod = comparableAnnual.find((item) => item.year === annualYear) ?? comparableAnnual[comparableAnnual.length - 1]
  const annualIndex = comparableAnnual.findIndex((item) => item.year === annualPeriod.year)
  const annualPrevious = comparableAnnual[Math.max(0, annualIndex - 1)]
  const current = useMemo(
    () => timeMode === 'annual' ? toRenderableAirPeriod(annualPeriod, metric) : airPeriods[airPeriods.length - 1],
    [annualPeriod, metric, timeMode],
  )
  const previous = useMemo(
    () => timeMode === 'annual'
      ? toRenderableAirPeriod(annualPrevious, metric)
      : airPeriods.find((item) => item.id === '2024-09') ?? airPeriods[0],
    [annualPrevious, metric, timeMode],
  )
  const record = current.records.find((item) => item.city === selected)!
  const recordValue = record[metric]
  const cityGeo = getCityGeo(selected)
  const comparison = timeMode === 'annual'
    ? compareAnnualAir(annualPrevious.year, annualPeriod.year, selected, metric)
    : compareAir(previous.id, current.id, selected, metric)
  const delta = comparison?.delta
  const average = getAverage(current, metric)
  const sorted = useMemo(
    () => [...current.records].sort((a, b) => a[metric] - b[metric]),
    [current.records, metric],
  )
  const rank = sorted.findIndex((item) => item.city === selected) + 1
  const cityIndex = guizhouCities.findIndex((item) => item.city === selected) + 1
  const history = useMemo(() => (timeMode === 'annual' ? annualAirPeriods : airPeriods).map((period) => ({
    id: period.id,
    label: period.shortLabel,
    value: period.records.find((item) => item.city === selected)?.[metric] ?? null,
  })), [selected, metric, timeMode])

  useEffect(() => {
    if (!comparableAnnual.some((period) => period.year === annualYear)) {
      setAnnualYear(comparableAnnual[comparableAnnual.length - 1].year)
    }
  }, [annualYear, comparableAnnual])

  useEffect(() => {
    const announce = selected === '铜仁市' && previousSelected.current !== '铜仁市'
    publishPageContext({ route: 'atlas', city: selected, metric, value: recordValue }, { announce })
    previousSelected.current = selected
  }, [selected, metric, recordValue, publishPageContext])

  useEffect(() => () => { if (scanTimer.current) clearTimeout(scanTimer.current) }, [])

  const selectCity = (city: CityKey) => {
    setSelected(city)
    setFocusSignal((value) => value + 1)
  }

  const startScan = () => {
    if (scanTimer.current) clearTimeout(scanTimer.current)
    setScanning(true)
    scanTimer.current = setTimeout(() => setScanning(false), 5000)
  }

  return (
    <div className="page atlas-page page-dark">
      <ContourField className="atlas-contour-field" label="SPATIAL TRUTH / WGS84 + DEM" />
      <header className="page-hero compact-hero geo-atlas-hero">
        <div>
          <p className="eyebrow"><span>02</span> GEO ECO OBSERVATORY · REAL TERRAIN</p>
          <h1>真实山地，<br />九城坐标。</h1>
        </div>
        <div className="page-hero-meta">
          <p><span>DEM SOURCE</span>Copernicus GLO-30</p>
          <p><span>SPATIAL REFERENCE</span>WGS84 · EPSG:4326</p>
          <p><span>OBSERVATION SLICE</span>{current.label} · {current.temporalResolution === 'year' ? '年均' : '月均'} · μg/m³</p>
        </div>
      </header>

      <section className="atlas-workspace geo-atlas-workspace">
        <div className="atlas-map-column">
          <div className="workspace-toolbar geo-toolbar" data-guide-target="atlas-filter">
            <div>
              <span className={`status-dot ${scanning ? 'is-pulsing' : ''}`} />
              <strong>GUIZHOU GEO ECO MONITOR / 贵州三维地理监测</strong>
              <small>{scanning ? 'SCANNING 09 CITY INDEXES' : 'SYS 02—DEM · LOCAL ASSET'}</small>
            </div>
            <div className="geo-time-mode" aria-label="选择空气数据时间粒度">
              <button type="button" className={timeMode === 'annual' ? 'is-active' : ''} onClick={() => setTimeMode('annual')}>ANNUAL / 年度档案</button>
              <button type="button" className={timeMode === 'monthly' ? 'is-active' : ''} onClick={() => setTimeMode('monthly')}>SNAPSHOT / 月度快照</button>
            </div>
            <MetricToggle metric={metric} onChange={setMetric} />
          </div>
          <div className="atlas-map-viewport geo-atlas-viewport" data-guide-target="atlas-cities">
            <LazyGuizhouTerrain3D
              records={current.records}
              metric={metric}
              selectedCity={selected}
              scanning={scanning}
              focusSignal={focusSignal}
              resetViewSignal={resetViewSignal}
              onSelectCity={selectCity}
            />
            <div className="geo-stage-heading">
              <span>DEM / ELEVATION FIELD</span>
              <strong>贵州省三维粒子地形</strong>
              <small>颜色仅编码高程与坡度，不表示污染空间分布</small>
            </div>
            {timeMode === 'annual' && (
              <div className="atlas-year-strip" aria-label={`${metricLabel[metric]}可用年度`} data-guide-target="atlas-filter">
                {Array.from({ length: 10 }, (_, index) => 2016 + index).map((year) => {
                  const available = comparableAnnual.some((period) => period.year === year)
                  return <button type="button" key={year} disabled={!available} className={annualPeriod.year === year ? 'is-active' : ''} onClick={() => setAnnualYear(year)}>{year}<i /></button>
                })}
              </div>
            )}
            <div className="geo-city-rail" aria-label="九个中心城市" data-guide-target="atlas-cities">
              {guizhouCities.map((city, index) => (
                <button
                  type="button"
                  className={city.city === selected ? 'is-active' : ''}
                  key={city.city}
                  onClick={() => selectCity(city.city)}
                >
                  <span>{String(index + 1).padStart(2, '0')}</span>
                  <strong>{city.city.replace('市', '')}</strong>
                  <small>{city.code}</small>
                </button>
              ))}
            </div>
            <div className="geo-stage-actions" data-guide-target="atlas-scan">
              <button type="button" className={scanning ? 'is-active' : ''} onClick={startScan} disabled={scanning}>
                <span>{scanning ? 'SCANNING' : 'SCAN GUIZHOU'}</span>
                {scanning ? '生态扫描进行中' : '扫描贵州'}
              </button>
              <button type="button" onClick={() => setResetViewSignal((value) => value + 1)}>
                <span>PROVINCE VIEW</span>返回全省
              </button>
            </div>
            <div className="atlas-scale geo-scale" aria-hidden="true"><i /><span>103.60°E—109.60°E</span><i /><span>24.60°N—29.22°N</span></div>
          </div>
        </div>

        <aside className="atlas-detail geo-atlas-detail">
          <div className="detail-kicker"><span>ACTIVE CITY INDEX</span><strong>{String(cityIndex).padStart(2, '0')} / 09</strong></div>
          <p className="geo-city-code">{cityGeo.code} · {cityGeo.nameEn}</p>
          <h2>{selected}</h2>
          <p className="detail-coordinate">{cityGeo.latitude.toFixed(5)}°N / {cityGeo.longitude.toFixed(5)}°E · WGS84</p>
          <p className="detail-value"><strong>{recordValue}</strong><span>μg/m³<br />{metricLabel[metric]} {current.temporalResolution === 'year' ? '年均' : '月均'}浓度</span></p>
          <div className="detail-delta">
            <span>{timeMode === 'annual' ? `较${annualPrevious.year}年` : '较2024年9月同期'}</span>
            <strong className={(delta ?? 0) <= 0 ? 'is-down' : 'is-up'}>{delta === undefined ? '暂无数据' : `${delta > 0 ? '+' : ''}${delta} μg/m³`}</strong>
          </div>
          <dl className="detail-list">
            <div><dt>九城平均</dt><dd>{average === null ? '暂无数据' : `${average.toFixed(1)} μg/m³`}</dd></div>
            <div><dt>九城低值排序</dt><dd>第 {rank} 位</dd></div>
            <div><dt>统计周期</dt><dd>{current.label} · {current.temporalResolution === 'year' ? '年度' : '月度'}</dd></div>
            <div><dt>空间标记</dt><dd>城市数据定位索引</dd></div>
          </dl>

          <button type="button" className="geo-history-toggle" onClick={() => setHistoryOpen((value) => !value)} aria-expanded={historyOpen}>
            <span>AVAILABLE HISTORY</span>{historyOpen ? '收起已核实节点' : '查看已有变化'}
          </button>
          {historyOpen && (
            <div className="geo-history" aria-label={`${selected}${metricLabel[metric]}已有数据节点`}>
              <HistoricalSignalTrace data={history} unit="μg/m³" activeId={current.id} ariaLabel={`${selected}${metricLabel[metric]}已有数据节点`} />
            </div>
          )}
          <MicroDataSpectrum records={current.records} metric={metric} selected={selected} onSelect={selectCity} frequencyLabel={current.temporalResolution === 'year' ? '年均' : '月均'} />
          <p className="scope-warning">城市点使用同一WGS84坐标投影并在DEM上采样贴地。它们不是33个国控站点的精确站址；缺少逐城年度值的年份已禁用。</p>
        </aside>
      </section>

      <section className="geo-method-strip" aria-label="地理数据方法说明">
        <article><span>01 / TERRAIN</span><strong>真实高程</strong><p>GLO-30源数据经离线重采样与省域掩膜裁剪，运行时不请求外部DEM。</p></article>
        <article><span>02 / POSITION</span><strong>统一坐标</strong><p>九城均使用EPSG:4326，并与地形共用同一局部等距投影函数。</p></article>
        <article><span>03 / COMPLIANCE</span><strong>地图校核</strong><p>轮廓以黔S（2025）006号标准地图校核；公开参赛前仍需完成地图合规复核。</p></article>
      </section>

      <section className="atlas-chart-section">
        <div className="section-heading split-heading light-heading">
          <div><p className="eyebrow">LINKED COMPARISON</p><h2>空间索引与城市谱线</h2></div>
          <p>{timeMode === 'annual' ? '选择年份后，九城浓度环、低值序位、摘要与三维地形同步更新；历史微趋势只连接连续的已核实年度节点。' : '点击城市谱线、城市列表或三维标签，地形镜头与右侧HUD同步聚焦；月度快照不与年度档案混用。'}</p>
        </div>
        {timeMode === 'annual' ? (
          <AirArchiveMatrix
            periods={annualAirPeriods}
            metric={metric}
            selected={selected}
            selectedYear={annualPeriod.year}
            onSelect={selectCity}
            onYearChange={setAnnualYear}
          />
        ) : (
          <AirBars records={current.records} metric={metric} selected={selected} onSelect={selectCity} frequencyLabel="月均" caption={`${current.label} · 9个中心城市 · 月度平均 · 来源见下方`} />
        )}
      </section>

      <details className="geo-source-note">
        <summary><span>GIS DATA / 地形与坐标来源</span><span>展开方法登记</span></summary>
        <div>
          <p><strong>DEM</strong> Copernicus DEM GLO-30，源分辨率约30米；浏览器资产为720×540网格，省内有效样本{guizhouTerrain.validSamples.toLocaleString()}个，高程范围{guizhouTerrain.elevationMeters.minimum}—{guizhouTerrain.elevationMeters.maximum}米。</p>
          <p><strong>轮廓校核</strong> {guizhouGeoSources.standardMap.name}，审图号{guizhouGeoSources.standardMap.reviewNumber}。当前站点为私有技术预览。</p>
          <p><strong>城市坐标</strong> {guizhouGeoSources.cityCoordinates.name}，{guizhouGeoSources.cityCoordinates.crs}，{guizhouGeoSources.cityCoordinates.license}。</p>
        </div>
      </details>
      <SourcePanel sourceIds={current.sourceIds} />
    </div>
  )
}
