import { lazy, Suspense } from 'react'
import type { TriadEcoCoreProps } from './TriadEcoCore'

const DeferredTriadEcoCore = lazy(() => import('./TriadEcoCore').then((module) => ({ default: module.TriadEcoCore })))

export function LazyTriadEcoCore(props: TriadEcoCoreProps) {
  return (
    <Suspense fallback={<div className="triad-core-loading"><span /><strong>生态核心接入中</strong><small>ECO CORE INITIALIZING</small></div>}>
      <DeferredTriadEcoCore {...props} />
    </Suspense>
  )
}
