import { useCallback, useEffect, useRef, useState } from 'react'

export type MascotAnimationState = 'idle' | 'hover' | 'greeting' | 'talking' | 'guiding'

export function useMascotAnimation(initial: MascotAnimationState = 'idle') {
  const [state, setState] = useState<MascotAnimationState>(initial)
  const timerRef = useRef<number | null>(null)

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) window.clearTimeout(timerRef.current)
    timerRef.current = null
  }, [])

  const play = useCallback((next: MascotAnimationState, duration?: number) => {
    clearTimer()
    setState(next)
    if (duration) timerRef.current = window.setTimeout(() => setState('idle'), duration)
  }, [clearTimer])

  useEffect(() => clearTimer, [clearTimer])
  return { state, play, setState }
}
