import { useEffect, useMemo, useRef, useState } from 'react'
import { MetricToggle } from '../components/AirVisuals'
import { BeforeAfterMirror } from '../components/BeforeAfterMirror'
import { ContourField } from '../components/ContourField'
import { CityBeaconMatrix, HistoricalSignalTrace } from '../components/EcoHudCharts'
import { LazyParticleTerrainScene } from '../components/LazyParticleTerrainScene'
import { SourcePanel } from '../components/SourcePanel'
import { TemporalCityExplorer } from '../components/TemporalCityExplorer'
import { TemporalDecadeControl } from '../components/TemporalDecadeControl'
import { useMascotGuideController } from '../components/qianling/MascotGuideController'
import {
  airPeriods,
  annualAirPeriods,
  compareAnnualAir,
  getAverage,
  getComparableAnnualAirPeriods,
  metricLabel,
  toRenderableAirPeriod,
  type AirMetric,
  type CityKey,
} from '../data/ecology'

type TemporalMode = 'history' | 'live'

function TrendTrace({ city, metric }: { city: CityKey; metric: AirMetric }) {
  const data = annualAirPeriods.map((period) => ({
    id: period.id,
    label: period.shortLabel,
    value: period.records.find((record) => record.city === city)?.[metric] ?? null,
  }))
  return <HistoricalSignalTrace data={data} unit="μg/m³" ariaLabel={`${city}${metricLabel[metric]}年度节点序列`} />
}

export function TimeLab() {
  const [timeIndex, setTimeIndex] = useState(6)
  const [metric, setMetric] = useState<AirMetric>('pm25')
  const [selected, setSelected] = useState<CityKey>('贵阳市')
  const [leftIndex, setLeftIndex] = useState(0)
  const [rightIndex, setRightIndex] = useState(6)
  const [divider, setDivider] = useState(50)
  const [mode, setMode] = useState<TemporalMode>('history')
  const [playing, setPlaying] = useState(false)
  const [scanning, setScanning] = useState(false)
  const [scanCycle, setScanCycle] = useState(0)
  const [resetViewSignal, setResetViewSignal] = useState(0)
  const scanTimer = useRef<number | null>(null)
  const { publishPageContext } = useMascotGuideController()

  const historyPeriods = useMemo(() => getComparableAnnualAirPeriods(metric), [metric])
  const renderPeriods = useMemo(() => historyPeriods.map((item) => toRenderableAirPeriod(item, metric)), [historyPeriods, metric])
  const latestMonthly = airPeriods[airPeriods.length - 1]
  const historyPeriod = renderPeriods[Math.min(timeIndex, renderPeriods.length - 1)]
  const period = mode === 'live' ? latestMonthly : historyPeriod
  const left = renderPeriods[Math.min(leftIndex, renderPeriods.length - 1)]
  const right = renderPeriods[Math.min(rightIndex, renderPeriods.length - 1)]
  const leftRecord = left.records.find((item) => item.city === selected)
  const rightRecord = right.records.find((item) => item.city === selected)
  const currentRecord = period.records.find((item) => item.city === selected)
  const comparison = compareAnnualAir(Number(left.id), Number(right.id), selected, metric)
  const average = useMemo(() => getAverage(period, metric), [period, metric])
  const baselinePeriod = mode === 'history' && timeIndex > 0 ? renderPeriods[timeIndex - 1] : undefined
  const baselineRecord = baselinePeriod?.records.find((item) => item.city === selected)
  const baselineValue = baselineRecord?.[metric]
  const currentValue = currentRecord?.[metric]
  const delta = currentValue !== undefined && baselineValue !== undefined ? currentValue - baselineValue : null

  useEffect(() => {
    publishPageContext({
      route: 'time',
      city: selected,
      metric,
      periodLabel: period.label,
      value: currentValue ?? null,
      baselineLabel: baselinePeriod?.label,
      baselineValue,
    })
  }, [selected, metric, period, currentValue, baselinePeriod, baselineValue, publishPageContext])

  useEffect(() => {
    setTimeIndex(historyPeriods.length - 1)
    setLeftIndex(0)
    setRightIndex(historyPeriods.length - 1)
    setPlaying(false)
  }, [historyPeriods])

  useEffect(() => {
    if (!playing) return
    const timer = window.setInterval(() => {
      setTimeIndex((index) => {
        if (index >= historyPeriods.length - 1) {
          setPlaying(false)
          return index
        }
        return index + 1
      })
    }, 2200)
    return () => window.clearInterval(timer)
  }, [playing, historyPeriods.length])

  useEffect(() => () => {
    if (scanTimer.current !== null) window.clearTimeout(scanTimer.current)
  }, [])

  const startScan = () => {
    if (scanTimer.current !== null) window.clearTimeout(scanTimer.current)
    setScanCycle((cycle) => cycle + 1)
    setScanning(true)
    scanTimer.current = window.setTimeout(() => setScanning(false), 3800)
  }

  const togglePlayback = () => {
    setMode('history')
    if (!playing && timeIndex === historyPeriods.length - 1) setTimeIndex(0)
    setPlaying((value) => !value)
  }

  const setTemporalMode = (nextMode: TemporalMode) => {
    setMode(nextMode)
    setPlaying(false)
  }

  const reset = () => {
    setTimeIndex(historyPeriods.length - 1)
    setMetric('pm25')
    setSelected('贵阳市')
    setLeftIndex(0)
    setRightIndex(historyPeriods.length - 1)
    setDivider(50)
    setMode('history')
    setPlaying(false)
    setScanning(false)
    setResetViewSignal((value) => value + 1)
  }

  return (
    <div className="page time-page page-dark">
      <ContourField variant="stream" className="lab-contour-field" label="TEMPORAL CALIBRATION FIELD" />

      <section className="temporal-console" aria-labelledby="temporal-console-title">
        <header className="temporal-console-header">
          <div>
            <p><span>03</span> ECO TEMPORAL CONTROL / GUIZHOU ECOLOGICAL OBSERVATORY</p>
            <h1 id="temporal-console-title">贵州生态<br /><strong>时空控制中心</strong></h1>
          </div>
          <div className="temporal-mode-switch" aria-label="时光实验室模式" data-guide-target="time-scene">
            <button type="button" className={mode === 'history' ? 'is-active' : ''} onClick={() => setTemporalMode('history')} aria-pressed={mode === 'history'}><i />TIME TRAVEL<small>时空回溯</small></button>
            <button type="button" className={mode === 'live' ? 'is-active' : ''} onClick={() => setTemporalMode('live')} aria-pressed={mode === 'live'}><i />LIVE MONITORING<small>实时监测</small></button>
          </div>
          <div className="temporal-system-state"><i className={mode === 'live' ? 'is-offline' : ''} /><span>{mode === 'live' ? 'API NOT CONNECTED' : 'ARCHIVE LINK ACTIVE'}</span><small>{period.label}</small></div>
        </header>

        <div className="temporal-console-grid">
          <aside className="temporal-hud temporal-hud-left">
            <div className="hud-index"><span>CTRL / 01</span><i /></div>
            <section>
              <p className="hud-label">OBSERVATION REGION</p>
              <h2>贵州省 <small>GUIZHOU</small></h2>
              <dl><div><dt>监测范围</dt><dd>9个中心城市 / 国控评价点位</dd></div><div><dt>时间分辨率</dt><dd>{mode === 'history' ? '城市年度' : '城市月度快照'}</dd></div><div><dt>有效节点</dt><dd>{String(historyPeriods.length).padStart(2, '0')} VERIFIED</dd></div></dl>
            </section>
            <section>
              <p className="hud-label">ECO INDICATOR</p>
              <MetricToggle metric={metric} onChange={setMetric} />
              <div className="hud-average"><span>{period.label} · 九城官方平均</span><strong key={`${period.id}-${metric}`}>{average?.toFixed(1) ?? '—'}</strong><small>μg/m³ · {metricLabel[metric]} · {period.temporalResolution === 'year' ? '年均' : '月均'}</small></div>
            </section>
            <section className="elevation-legend">
              <p className="hud-label">TERRAIN COLOR LEGEND</p>
              <div><i /><span><b>LOW</b><b>HIGH</b></span></div>
              <p>颜色仅编码程序化高程；九城光点承载真实数据，省级平均值只触发全局微光反馈，不生成污染空间分布。</p>
            </section>
            <section className="hud-actions" data-guide-target="time-scene">
              <button type="button" className={scanning ? 'is-active' : ''} onClick={startScan}><span>{scanning ? 'SCANNING' : 'START SCAN'}</span>{scanning ? '扫描进行中' : '开始三维生态扫描'}<i /></button>
              <button type="button" onClick={() => setResetViewSignal((value) => value + 1)}><span>RESET VIEW</span>恢复默认视角 ↺</button>
              <small>扫描是视觉化查询过程，不表示正在执行实际遥感扫描。</small>
            </section>
            <footer><span>SOURCE</span><p>贵州省生态环境厅生态环境状况公报</p><small>{period.sourceIds.length} SOURCE LINK{period.sourceIds.length > 1 ? 'S' : ''} / VERIFIED</small></footer>
          </aside>

          <div className="temporal-stage" data-guide-target="time-scene">
            <LazyParticleTerrainScene
              average={average}
              metric={metric}
              periodLabel={period.label}
              records={period.records}
              selectedCity={selected}
              scanning={scanning}
              pulseKey={`${period.id}-${metric}-${scanCycle}`}
              resetViewSignal={resetViewSignal}
              onSelectCity={setSelected}
            />
            <div className="temporal-stage-topline"><span>PARTICLE ECO TERRAIN / CONCEPT MODEL</span><i /><b>{metricLabel[metric]} DATA BEACONS</b></div>
            <div className="temporal-axis-mark axis-x">X / 106°—109° E</div>
            <div className="temporal-axis-mark axis-y">Y / 25°—29° N</div>
            <div className="temporal-stage-title"><span>ACTIVE TEMPORAL NODE</span><strong>{period.shortLabel}</strong><small>{mode === 'live' ? 'LATEST VERIFIED SNAPSHOT / 非实时流' : 'ANNUAL VERIFIED ARCHIVE'}</small></div>
            <div className="temporal-selected-tag"><span>SELECTED BEACON / {selected.replace('市', '')}</span><strong>{currentValue ?? '—'} <i>μg/m³</i></strong><small>{metricLabel[metric]} · 城市{period.temporalResolution === 'year' ? '年均' : '月均'}浓度</small></div>
            <div className={`temporal-scan-status ${scanning ? 'is-active' : ''}`} aria-live="polite"><i /><span>{scanning ? 'VISUAL QUERY IN PROGRESS' : 'SCAN ARRAY STANDBY'}</span><b>{scanning ? '依次高亮九城真实监测点' : '点击开始扫描'}</b></div>
          </div>

          <aside className="temporal-hud temporal-hud-right">
            <div className="hud-index"><span>DATA / 02</span><i /></div>
            <section className="selected-reading">
              <p className="hud-label">ACTIVE CITY SIGNAL</p>
              <h2>{selected.replace('市', '')}<small>{selected}</small></h2>
              <strong>{currentValue ?? '—'}<i>μg/m³</i></strong>
              <p>{metricLabel[metric]} · {period.label}</p>
              <div className={delta === null ? 'is-missing' : delta <= 0 ? 'is-lower' : 'is-higher'}>
                <span>{baselinePeriod ? `VS ${baselinePeriod.label}` : 'PREVIOUS VERIFIED YEAR'}</span>
                <b>{delta === null ? '暂无可比节点' : `${delta > 0 ? '+' : ''}${delta} μg/m³`}</b>
              </div>
            </section>
            <section>
              <p className="hud-label">VERIFIED NODE TRACE</p>
              <TrendTrace city={selected} metric={metric} />
            </section>
            <section className="city-beacon-list">
              <p className="hud-label">09 CITY BEACONS</p>
              <CityBeaconMatrix records={period.records} metric={metric} selected={selected} onSelect={setSelected} />
            </section>
            <section className={`live-link-status ${mode === 'live' ? 'is-visible' : ''}`}>
              <p className="hud-label">LIVE DATA LINK</p>
              <div><i /><span>OFFLINE / 未连接实时API</span></div>
              <p>当前仅显示最新已核实月度快照：{latestMonthly.label}。不会用随机数模拟实时变化。</p>
            </section>
            <footer><span>UPDATED</span><p>{period.label} OFFICIAL {period.temporalResolution === 'year' ? 'ANNUAL BULLETIN' : 'MONTHLY REPORT'}</p><small>VALIDATION / PASSED</small></footer>
          </aside>
        </div>

        <div className="temporal-bottom-control">
          <TemporalDecadeControl periods={renderPeriods} activeIndex={Math.min(timeIndex, renderPeriods.length - 1)} playing={playing} disabled={mode === 'live'} onChange={setTimeIndex} onTogglePlay={togglePlayback} />
          <button type="button" className="temporal-reset-all" onClick={reset}>RESET SYSTEM / 恢复初始状态 ↺</button>
        </div>
      </section>

      <TemporalCityExplorer
        records={period.records}
        periods={annualAirPeriods}
        metric={metric}
        selected={selected}
        selectedYear={mode === 'history' ? Number(period.id.slice(0, 4)) : Number(historyPeriod.id.slice(0, 4))}
        periodLabel={period.label}
        onSelectCity={setSelected}
        onSelectYear={(year) => {
          const nextIndex = renderPeriods.findIndex((item) => Number(item.id.slice(0, 4)) === year)
          if (nextIndex >= 0) {
            setMode('history')
            setPlaying(false)
            setTimeIndex(nextIndex)
          }
        }}
      />

      <section className="compare-lab" id="time-comparator">
        <div className="section-heading split-heading light-heading">
          <div><p className="eyebrow">DUAL-TIME OPTICAL COMPARATOR</p><h2>双时刻对照镜</h2></div>
          <p>选择两个具有逐城官方年均值的年份，再拖动分割线。缺少逐城PM值的年份不会被伪造或开放。</p>
        </div>
        <div className="compare-controls">
          <label>LEFT / 左侧年份<select value={Math.min(leftIndex, renderPeriods.length - 1)} onChange={(event) => setLeftIndex(Number(event.target.value))}>{renderPeriods.map((item, index) => <option value={index} key={item.id}>{item.label}</option>)}</select></label>
          <label>LOCATION / 对照城市<select value={selected} onChange={(event) => setSelected(event.target.value as CityKey)}>{renderPeriods[0].records.map((item) => <option key={item.city}>{item.city}</option>)}</select></label>
          <label>RIGHT / 右侧年份<select value={Math.min(rightIndex, renderPeriods.length - 1)} onChange={(event) => setRightIndex(Number(event.target.value))}>{renderPeriods.map((item, index) => <option value={index} key={item.id}>{item.label}</option>)}</select></label>
        </div>
        <BeforeAfterMirror leftLabel={left.label} rightLabel={right.label} leftValue={leftRecord?.[metric] ?? null} rightValue={rightRecord?.[metric] ?? null} city={selected} metric={metric} divider={divider} delta={comparison?.delta ?? null} percent={comparison?.percent ?? null} isYearOnYear={comparison?.isYearOnYear ?? false} temporalResolution="year" onDividerChange={setDivider} />
      </section>
      <SourcePanel sourceIds={Array.from(new Set(annualAirPeriods.flatMap((item) => item.sourceIds)))} />
    </div>
  )
}
