import { useEffect, useMemo, useState } from 'react'
import type { RouteKey } from '../App'

export type GuideMode = 'welcome' | 'on' | 'off'

type GuideHint = { id: string; target: string; text: string }

const mascotHint: GuideHint = { id: 'mascot', target: 'mascot', text: '点黔小灵打开生态讲解；可拖动角色，方向键也能移动。' }

const routeHints: Record<RouteKey, GuideHint[]> = {
  prologue: [
    { id: 'themes', target: 'prologue-themes', text: '切换 AIR、WATER、FOREST，中央生态核心会同步改变。' },
    { id: 'core', target: 'prologue-core', text: '拖动核心旋转，滚轮缩放；点重置视角回到初始位置。' },
    { id: 'entry', target: 'prologue-entry', text: '从主题入口进入对应章节，或开始生态唤醒动画。' },
  ],
  atlas: [
    { id: 'filter', target: 'atlas-filter', text: '选择 PM 指标、年度或月度档案；有数据的年份才可选。' },
    { id: 'cities', target: 'atlas-cities', text: '点击地图或城市列表，联动地形聚焦和右侧数据。' },
    { id: 'scan', target: 'atlas-scan', text: '扫描贵州会依次高亮城市；返回全省可重置视角。' },
  ],
  time: [
    { id: 'scene', target: 'time-scene', text: '切换历史/快照模式；拖动中央地形旋转、滚轮缩放，扫描与重置在左侧。实时 API 当前未连接。' },
    { id: 'axis', target: 'time-axis', text: '点击亮起年份回溯，播放只经过已核实的数据节点。' },
    { id: 'comparison', target: 'time-comparison', text: '点击地图城市或趋势节点联动；对照镜分割线可拖动。' },
  ],
  symbiosis: [
    { id: 'water', target: 'symbiosis-water', text: '切换水指标并悬停趋势节点查看对应年度值；可导出 PNG。' },
    { id: 'forest', target: 'symbiosis-forest', text: '切换森林指标；注意覆盖率与营造林面积是不同口径。' },
  ],
  story: [
    { id: 'scroll', target: 'story-scroll', text: '向下滚动逐幕阅读；右侧章节刻度可跳转到对应段落。' },
    { id: 'ending', target: 'story-ending', text: '在长卷结尾可返回时光实验室或重新开始序章。' },
  ],
}

export function InteractionGuide({ route, mode, onEnable, onSkip, onToggle }: {
  route: RouteKey
  mode: GuideMode
  onEnable: () => void
  onSkip: () => void
  onToggle: () => void
}) {
  const [dismissed, setDismissed] = useState<string[]>([])
  const hints = useMemo(() => [...routeHints[route], mascotHint].filter((hint) => !dismissed.includes(hint.id)), [route, dismissed])

  useEffect(() => setDismissed([]), [route, mode])

  useEffect(() => {
    if (mode !== 'on') return
    const dismissTargetHint = (event: Event) => {
      const target = event.target
      if (!(target instanceof Element)) return
      const id = target.closest<HTMLElement>('[data-guide-target]')?.dataset.guideTarget
      if (!id) return
      const hint = [...routeHints[route], mascotHint].find((item) => item.target === id)
      if (hint) setDismissed((current) => current.includes(hint.id) ? current : [...current, hint.id])
    }
    document.addEventListener('click', dismissTargetHint, true)
    document.addEventListener('change', dismissTargetHint, true)
    document.addEventListener('pointerup', dismissTargetHint, true)
    return () => {
      document.removeEventListener('click', dismissTargetHint, true)
      document.removeEventListener('change', dismissTargetHint, true)
      document.removeEventListener('pointerup', dismissTargetHint, true)
    }
  }, [mode, route])

  if (mode === 'off') return null

  return (
    <section className={`interaction-guide-popover ${mode === 'welcome' ? 'is-welcome' : ''}`} aria-labelledby="interaction-guide-title" aria-live="polite">
      <header><span>{mode === 'welcome' ? 'QUICK START / 首次使用' : `${routeHints[route].length} 个章节提示`}</span><strong id="interaction-guide-title">{mode === 'welcome' ? '交互操作指引' : '本页可操作区域'}</strong></header>
      <ul>{hints.map((hint) => (
        <li key={hint.id}>
          <i aria-hidden="true" />
          <span>{hint.text}</span>
          {mode === 'on' && <button type="button" aria-label="收起这条操作提示" onClick={() => setDismissed((current) => [...current, hint.id])}>×</button>}
        </li>
      ))}</ul>
      {mode === 'welcome' ? (
        <div className="interaction-guide-actions"><button type="button" onClick={onEnable}>开启指引</button><button type="button" onClick={onSkip}>跳过</button></div>
      ) : (
        <button type="button" className="interaction-guide-close" onClick={onToggle}>关闭交互指引</button>
      )}
    </section>
  )
}
