import rawDataset from './ecology-data.json'
import rawAnnualAir from './historical/air-quality-annual.json'
import rawAnnualWater from './historical/water-quality-annual.json'
import rawAnnualForest from './historical/forest-annual.json'
import rawHistoricalSources from './metadata/data-sources.json'

export type CityKey =
  | '贵阳市'
  | '遵义市'
  | '六盘水市'
  | '安顺市'
  | '毕节市'
  | '铜仁市'
  | '凯里市'
  | '都匀市'
  | '兴义市'

export type AirMetric = 'pm25' | 'pm10'
export type TemporalResolution = 'month' | 'year'
export type GeographicScope = 'city' | 'province'
export type VerificationStatus = 'verified' | 'cross_checked' | 'missing'

export interface AirCityRecord {
  city: CityKey
  pm25: number
  pm10: number
  x: number
  y: number
}

export interface AirPeriod {
  id: string
  label: string
  shortLabel: string
  scope: string
  sourceId: string
  sourceIds: string[]
  temporalResolution: TemporalResolution
  publishedAverage: Record<AirMetric, number>
  records: AirCityRecord[]
}

export interface AnnualAirCityRecord {
  city: CityKey
  pm25: number | null
  pm10: number | null
  goodDayRate: number
  x: number
  y: number
}

export interface AnnualAirPeriod {
  year: number
  id: string
  label: string
  shortLabel: string
  scope: string
  sourceId: string
  sourceIds: string[]
  temporalResolution: 'year'
  publishedAverage: Record<AirMetric, number> & { goodDayRate: number }
  records: AnnualAirCityRecord[]
  missingReason: string | null
}

export interface HistoricalIndicatorRecord {
  year: number
  month: null
  location: '贵州省'
  indicator: string
  value: number | null
  unit: string
  scope: string
  frequency: 'annual'
  source: string
  sourceUrl: string
  sourceIds: string[]
  verified: boolean
  verificationStatus: 'verified' | 'cross_checked'
  methodology: string
  methodologyGroup: string
  locator: string
  missingReason: string | null
}

export interface SourceRecord {
  id: string
  title: string
  publisher: string
  url: string
  publishedDate: string
  accessedDate: string
  documentPeriod: string
  sourceType: string
  locator: string
  status: 'verified' | 'cross_checked'
  note: string
  period: string
  scope: string
}

export interface EcologyIndicatorRecord {
  id: string
  metric: string
  name: string
  value: number | null
  unit: string
  period: string
  temporalResolution: TemporalResolution
  geographicScope: GeographicScope
  geography: string
  monitoringScope: string
  sourceIds: string[]
  status: VerificationStatus
  missingReason?: string
  transformation?: string
}

interface EcologyDataset {
  schemaVersion: string
  lastReviewed: string
  missingValuePolicy: string
  sources: Omit<SourceRecord, 'period' | 'scope'>[]
  airQuality: {
    metrics: AirMetric[]
    unit: 'μg/m³'
    geographicScope: 'city'
    monitoringScope: string
    periods: Array<{
      id: string
      label: string
      shortLabel: string
      temporalResolution: 'month'
      sourceIds: string[]
      publishedAverage: Record<AirMetric, number>
      records: Array<{ city: CityKey; pm25: number; pm10: number }>
    }>
  }
  waterEnvironment: EcologyIndicatorRecord[]
  forestEcology: EcologyIndicatorRecord[]
}

export const ecologyDataset = rawDataset as EcologyDataset

const locations: Record<CityKey, { x: number; y: number }> = {
  贵阳市: { x: 49, y: 51 },
  遵义市: { x: 49, y: 24 },
  六盘水市: { x: 23, y: 54 },
  安顺市: { x: 38, y: 61 },
  毕节市: { x: 27, y: 34 },
  铜仁市: { x: 77, y: 34 },
  凯里市: { x: 67, y: 57 },
  都匀市: { x: 56, y: 70 },
  兴义市: { x: 25, y: 82 },
}

const historicalSourceRegistry: SourceRecord[] = rawHistoricalSources.sources.map((source) => ({
  id: source.id,
  title: source.title,
  publisher: source.publisher,
  url: source.url,
  publishedDate: `${source.period}-12-31`,
  accessedDate: rawHistoricalSources.reviewedAt,
  documentPeriod: `${source.period}年`,
  sourceType: 'official_annual_report',
  locator: source.locators.join('；'),
  status: source.status as 'verified' | 'cross_checked',
  note: source.status === 'verified' ? '已逐项核对报告正文、表格或图示。' : '数值已交叉复核；原始发布页并非生态环境厅主站。',
  period: `${source.period}年`,
  scope: source.locators.join('；'),
}))

export const sourceRegistry: SourceRecord[] = [
  ...ecologyDataset.sources.map((source) => ({
    ...source,
    period: source.documentPeriod,
    scope: source.locator,
  })),
  ...historicalSourceRegistry.filter((historical) => !ecologyDataset.sources.some((source) => source.id === historical.id)),
]

export const airPeriods: AirPeriod[] = ecologyDataset.airQuality.periods.map((period) => ({
  ...period,
  scope: ecologyDataset.airQuality.monitoringScope,
  sourceId: period.sourceIds[0],
  records: period.records.map((record) => ({ ...record, ...locations[record.city] })),
}))

export const annualAirPeriods: AnnualAirPeriod[] = rawAnnualAir.periods.map((period) => ({
  ...period,
  id: String(period.year),
  scope: period.scope,
  sourceId: period.sourceIds[0],
  records: period.records.map((record) => ({ ...record, ...locations[record.city as CityKey] })) as AnnualAirCityRecord[],
})) as AnnualAirPeriod[]

export const waterAnnual = rawAnnualWater.records as HistoricalIndicatorRecord[]
export const forestAnnual = rawAnnualForest.records as HistoricalIndicatorRecord[]

const formatPeriod = (period: string) => period.includes('-')
  ? `${period.slice(0, 4)}年${Number(period.slice(5))}月`
  : `${period}年`

export const waterEvidence = ecologyDataset.waterEnvironment
  .filter((item): item is EcologyIndicatorRecord & { value: number } => item.value !== null)
  .map((item) => ({
    ...item,
    label: item.name,
    period: formatPeriod(item.period),
    scope: `${item.geography}｜${item.monitoringScope}`,
    sourceId: item.sourceIds[0],
  }))

export const forestEvidence = ecologyDataset.forestEcology
  .filter((item): item is EcologyIndicatorRecord & { value: number } => item.metric === 'afforestation_area' && item.value !== null)
  .map((item) => ({
    ...item,
    year: Number(item.period),
    label: item.name,
    sourceId: item.sourceIds[0],
  }))

export const forestCoverage = ecologyDataset.forestEcology
  .filter((item) => item.metric === 'forest_coverage_rate')

export const forestRestoration = ecologyDataset.forestEcology
  .find((item) => item.metric === 'karst_desertification_restoration_area')

export const getAverage = (period: AirPeriod, metric: AirMetric) => {
  if (!period.records.length) return null
  return period.publishedAverage[metric]
}

export const getSource = (id: string) => sourceRegistry.find((item) => item.id === id)

export const getAirPeriod = (id: string) => airPeriods.find((period) => period.id === id)

export const getAirRecord = (periodId: string, city: CityKey) =>
  getAirPeriod(periodId)?.records.find((record) => record.city === city)

export const compareAir = (leftId: string, rightId: string, city: CityKey, metric: AirMetric) => {
  const left = getAirRecord(leftId, city)?.[metric]
  const right = getAirRecord(rightId, city)?.[metric]
  if (left === undefined || right === undefined) return null
  const delta = right - left
  return {
    left,
    right,
    delta,
    percent: left === 0 ? null : delta / left * 100,
    isYearOnYear: leftId.slice(5) === rightId.slice(5),
  }
}

export const getAnnualAirPeriod = (year: number | string) => annualAirPeriods.find((period) => period.year === Number(year))

export const getAnnualAirRecord = (year: number | string, city: CityKey) =>
  getAnnualAirPeriod(year)?.records.find((record) => record.city === city)

export const compareAnnualAir = (leftYear: number, rightYear: number, city: CityKey, metric: AirMetric) => {
  const left = getAnnualAirRecord(leftYear, city)?.[metric]
  const right = getAnnualAirRecord(rightYear, city)?.[metric]
  if (left === null || left === undefined || right === null || right === undefined) return null
  const delta = right - left
  return { left, right, delta, percent: left === 0 ? null : delta / left * 100, isYearOnYear: true }
}

export const getComparableAnnualAirPeriods = (metric: AirMetric) => annualAirPeriods.filter((period) =>
  period.records.length === 9 && period.records.every((record) => record[metric] !== null),
)

export const toRenderableAirPeriod = (period: AnnualAirPeriod, metric: AirMetric): AirPeriod => ({
  id: period.id,
  label: period.label,
  shortLabel: period.shortLabel,
  scope: period.scope,
  sourceId: period.sourceId,
  sourceIds: period.sourceIds,
  temporalResolution: 'year',
  publishedAverage: { pm25: period.publishedAverage.pm25, pm10: period.publishedAverage.pm10 },
  records: period.records.map((record) => {
    const selectedValue = record[metric]
    if (selectedValue === null) throw new Error(`${period.year} ${record.city} ${metric} is not renderable`)
    return {
      city: record.city,
      pm25: record.pm25 ?? selectedValue,
      pm10: record.pm10 ?? selectedValue,
      x: record.x,
      y: record.y,
    }
  }),
})

export const canCompareIndicators = (left: EcologyIndicatorRecord, right: EcologyIndicatorRecord) =>
  left.value !== null
  && right.value !== null
  && left.metric === right.metric
  && left.unit === right.unit
  && left.temporalResolution === right.temporalResolution
  && left.geographicScope === right.geographicScope
  && left.geography === right.geography
  && left.monitoringScope === right.monitoringScope

export const metricLabel: Record<AirMetric, string> = {
  pm25: 'PM2.5',
  pm10: 'PM10',
}

export const datasetSummary = {
  sourceCount: sourceRegistry.length,
  verifiedAirPeriods: airPeriods.length,
  annualAirPeriods: annualAirPeriods.length,
  lastReviewed: ecologyDataset.lastReviewed,
}
