import { lazy, Suspense } from 'react'
import type { GuizhouTerrain3DProps } from './GuizhouTerrain3D'

const GuizhouTerrain3D = lazy(() => import('./GuizhouTerrain3D').then((module) => ({ default: module.GuizhouTerrain3D })))

export function LazyGuizhouTerrain3D(props: GuizhouTerrain3DProps) {
  return (
    <Suspense fallback={<div className="geo-terrain-loader"><span /><strong>正在初始化三维地理引擎</strong><small>WEBGL / DEM</small></div>}>
      <GuizhouTerrain3D {...props} />
    </Suspense>
  )
}

