import { useEffect, useRef, useState, type CSSProperties } from 'react'
import { SourcePanel } from '../components/SourcePanel'
import { ContourField } from '../components/ContourField'
import { airPeriods, datasetSummary, forestEvidence, getAverage, waterEvidence } from '../data/ecology'
import { useMotionProfile } from '../hooks/useMotionProfile'
import forestScene from '../assets/forest-cinematic.jpg'
import waterScene from '../assets/water-cinematic.jpg'
import { useMascotGuideController } from '../components/qianling/MascotGuideController'

const latestAir = airPeriods[airPeriods.length - 1]
const baselineAir = airPeriods.find((item) => item.id === '2024-09') ?? airPeriods[0]
const latestPm25 = getAverage(latestAir, 'pm25') ?? 0
const baselinePm25 = getAverage(baselineAir, 'pm25') ?? 0
const pm25Percent = baselinePm25 ? (latestPm25 - baselinePm25) / baselinePm25 * 100 : null
const annualWater = waterEvidence.find((item) => item.temporalResolution === 'year')
const latestForest = forestEvidence[forestEvidence.length - 1]
const acts = [
  {
    index: '第一幕', title: '山城之息', en: 'BREATH OF THE MOUNTAINS',
    text: `空气变化先抵达城市。${latestAir.label}，贵州9个中心城市PM2.5月均浓度为6—15微克/立方米，九城平均${latestPm25.toFixed(0)}微克/立方米。`,
    value: latestPm25.toFixed(0), unit: 'μg/m³', note: `${latestAir.label}九城PM2.5平均`,
  },
  {
    index: '第二幕', title: '江河之脉', en: 'PULSE OF THE RIVERS',
    text: `水质数据依附于断面和流域。${annualWater?.period ?? '暂无时期'}贵州主要河流出境断面水质优良率为${annualWater?.value ?? '暂无数据'}%；它描述的是出境断面，不代表每一条河流的每一段。`,
    value: String(annualWater?.value ?? '—'), unit: annualWater?.unit ?? '', note: `${annualWater?.period ?? '暂无'}主要河流出境断面`,
  },
  {
    index: '第三幕', title: '青山之境', en: 'REALM OF THE FORESTS',
    text: `${latestForest.year}年贵州完成营造林面积${latestForest.value}${latestForest.unit}。这个数字记录年度行动，但森林生态仍需要覆盖率、质量和长期连续观测共同解释。`,
    value: String(latestForest.value), unit: latestForest.unit, note: `${latestForest.year}年完成营造林面积`,
  },
  {
    index: '终章', title: '时间留下的生态印记', en: 'WHAT TIME LEAVES BEHIND',
    text: `同月对照显示，${latestAir.label}九城PM2.5平均值较${baselineAir.label}${(pm25Percent ?? 0) <= 0 ? '下降' : '上升'}${Math.abs(pm25Percent ?? 0).toFixed(1)}%。水环境选用的年度指标保持高位；营造林年度完成量增加，但不能替代森林质量判断。`,
    value: pm25Percent === null ? '—' : `${pm25Percent < 0 ? '−' : '+'}${Math.abs(pm25Percent).toFixed(1)}`, unit: '%', note: `九城PM2.5 ${latestAir.label}同比`,
  },
]
const sceneImages = [forestScene, waterScene, forestScene, forestScene]

export function EcoStory() {
  const [active, setActive] = useState(0)
  const [sceneProgress, setSceneProgress] = useState(0)
  const activeRef = useRef(0)
  const progressRef = useRef(0)
  const actRefs = useRef<Array<HTMLElement | null>>([])
  const motionProfile = useMotionProfile()
  const { publishPageContext } = useMascotGuideController()

  useEffect(() => {
    publishPageContext({ route: 'story', act: active, progress: progressRef.current })
  }, [active, publishPageContext])

  useEffect(() => {
    let frame = 0
    const update = () => {
      frame = 0
      const anchor = window.innerHeight * .52
      let bestIndex = 0
      let bestDistance = Number.POSITIVE_INFINITY
      let bestProgress = 0
      actRefs.current.forEach((element, index) => {
        if (!element) return
        const rect = element.getBoundingClientRect()
        const distance = anchor < rect.top ? rect.top - anchor : anchor > rect.bottom ? anchor - rect.bottom : 0
        if (distance < bestDistance) {
          bestDistance = distance
          bestIndex = index
          bestProgress = Math.min(1, Math.max(0, (anchor - rect.top) / Math.max(1, rect.height)))
        }
      })
      if (bestIndex !== activeRef.current) {
        activeRef.current = bestIndex
        setActive(bestIndex)
      }
      const roundedProgress = Math.round(bestProgress * 100) / 100
      if (Math.abs(roundedProgress - progressRef.current) >= .02) {
        progressRef.current = roundedProgress
        setSceneProgress(roundedProgress)
      }
    }
    const requestUpdate = () => {
      if (!frame) frame = window.requestAnimationFrame(update)
    }
    update()
    window.addEventListener('scroll', requestUpdate, { passive: true })
    window.addEventListener('resize', requestUpdate)
    return () => {
      if (frame) window.cancelAnimationFrame(frame)
      window.removeEventListener('scroll', requestUpdate)
      window.removeEventListener('resize', requestUpdate)
    }
  }, [])

  const scrollToAct = (index: number) => actRefs.current[index]?.scrollIntoView({
    behavior: motionProfile === 'full' ? 'smooth' : 'auto',
    block: 'center',
  })

  return (
    <div className="page story-page page-dark">
      <header className="story-opening">
        <div className="story-opening-image" style={{ backgroundImage: `url(${forestScene})` }} aria-hidden="true" />
        <ContourField className="story-opening-contours" label="A SCROLL OF ECOLOGICAL TIME" />
        <p className="eyebrow"><span>05</span> 生态长卷 · ECO STORY</p>
        <h1>山水不是静止的风景，<br />而是一份仍在书写的档案。</h1>
        <p>向下滚动，穿过空气、江河与森林。每一幕只说数据能够证明的事。</p>
        <span className="story-scroll">SCROLL · 纵向展开</span>
      </header>

      <section className="story-scroll-layout" data-guide-target="story-scroll">
        <div
          className={`story-stage stage-${active}`}
          data-motion={motionProfile}
          style={{ '--scene-progress': sceneProgress } as CSSProperties}
          aria-live="polite"
          aria-label={`${acts[active].index}，${acts[active].title}`}
        >
          <div className="story-scene-image" style={{ backgroundImage: `url(${sceneImages[active]})` }} aria-hidden="true" />
          <div className="story-cinematic-grade" aria-hidden="true" />
          <p className="story-scene-label"><span>{acts[active].index}</span><i /><strong>{Math.round(sceneProgress * 100)}%</strong></p>
          <div className="story-sun" />
          <div className="story-mountain m1" /><div className="story-mountain m2" /><div className="story-mountain m3" />
          <div className="story-river" />
          <div className="story-trees">{Array.from({ length: motionProfile === 'full' ? 14 : 8 }, (_, i) => <i key={i} />)}</div>
          <div className="story-data-ghost"><strong>{acts[active].value}</strong><span>{acts[active].unit}</span></div>
          <p className="story-scene-note">ORIGINAL ECOLOGICAL ART SCENE · 非遥感/监测影像</p>
          <div className="story-progress" aria-label="长卷章节导航" data-guide-target="story-scroll">
            {acts.map((act, index) => (
              <button
                type="button"
                key={act.title}
                className={index === active ? 'is-active' : ''}
                aria-label={`前往${act.index}：${act.title}`}
                aria-current={index === active ? 'step' : undefined}
                onClick={() => scrollToAct(index)}
              />
            ))}
          </div>
        </div>
        <div className="story-acts">
          {acts.map((act, index) => (
            <article
              ref={(element) => { actRefs.current[index] = element }}
              className={`story-act ${index === active ? 'is-active' : index < active ? 'is-past' : 'is-future'}`}
              key={act.title}
              data-index={index}
              aria-current={index === active ? 'step' : undefined}
            >
              <span className="story-boundary story-boundary-start" aria-hidden="true">BEGIN · {String(index + 1).padStart(2, '0')}</span>
              <span className="act-ghost" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>
              <div className="story-act-copy">
                <p className="eyebrow">{act.index} · {act.en}</p>
                <h2>{act.title}</h2>
                <p>{act.text}</p>
                <div className="story-metric"><strong>{act.value}</strong><span>{act.unit}<small>{act.note}</small></span></div>
                {index === 3 && <p className="scope-warning">变化不是单向叙事：指标改善、保持或缺失，都应被如实呈现。</p>}
              </div>
              <span className="story-boundary story-boundary-end" aria-hidden="true">END · {String(index + 1).padStart(2, '0')}</span>
            </article>
          ))}
        </div>
      </section>

      <section className="story-epilogue" data-guide-target="story-ending">
        <p className="eyebrow">EPILOGUE</p>
        <h2>时间不替我们下结论。<br />它只留下证据。</h2>
        <p>《黔境·生态时光》以{datasetSummary.sourceCount}项公开来源构成一条可追溯的贵州生态叙事。所有视觉均为原创数据表达，不绘制未经授权的行政区边界，不把演示推断伪装成官方结论。</p>
        <div className="epilogue-actions"><a href="#/time">回到时光实验室</a><a href="#/prologue">重返山水序章</a></div>
      </section>
      <SourcePanel sourceIds={['air-2025-09', 'air-2024-09', 'air-2025-02', 'stats-2025', 'stats-2021']} title="完整数据来源与作品说明" />
    </div>
  )
}
