import { useEffect, useMemo, useState } from 'react'
import { SiteNav } from './components/SiteNav'
import { Prologue } from './pages/Prologue'
import { Atlas } from './pages/Atlas'
import { TimeLab } from './pages/TimeLab'
import { Symbiosis } from './pages/Symbiosis'
import { EcoStory } from './pages/EcoStory'
import { useMotionProfile } from './hooks/useMotionProfile'
import { EcoGuide } from './components/EcoGuide'
import { MascotGuideController } from './components/qianling/MascotGuideController'
import { type GuideMode } from './components/InteractionGuide'

export type RouteKey = 'prologue' | 'atlas' | 'time' | 'symbiosis' | 'story'

export const routes: Array<{ key: RouteKey; number: string; zh: string; en: string }> = [
  { key: 'prologue', number: '01', zh: '山水序章', en: 'PROLOGUE' },
  { key: 'atlas', number: '02', zh: '黔境图谱', en: 'ECO ATLAS' },
  { key: 'time', number: '03', zh: '时光实验室', en: 'TIME LAB' },
  { key: 'symbiosis', number: '04', zh: '山水共生', en: 'SYMBIOSIS' },
  { key: 'story', number: '05', zh: '生态长卷', en: 'ECO STORY' },
]

const routeFromHash = (): RouteKey => {
  const key = window.location.hash.replace('#/', '').split('?')[0] as RouteKey
  return routes.some((item) => item.key === key) ? key : 'prologue'
}

export default function App() {
  const [route, setRoute] = useState<RouteKey>(routeFromHash)
  const [guideMode, setGuideMode] = useState<GuideMode>(() => {
    try {
      const saved = window.localStorage.getItem('qianjing-interaction-guide-v1')
      return saved === 'on' ? 'on' : saved === 'off' ? 'off' : 'welcome'
    } catch { return 'welcome' }
  })
  const motionProfile = useMotionProfile()

  const setGuidePreference = (mode: Exclude<GuideMode, 'welcome'>) => {
    try { window.localStorage.setItem('qianjing-interaction-guide-v1', mode) } catch { /* Keep this session usable when storage is blocked. */ }
    setGuideMode(mode)
  }

  useEffect(() => {
    const onHashChange = () => {
      setRoute(routeFromHash())
      window.scrollTo({ top: 0, behavior: 'auto' })
    }
    window.addEventListener('hashchange', onHashChange)
    return () => window.removeEventListener('hashchange', onHashChange)
  }, [])

  useEffect(() => {
    document.body.dataset.route = route
  }, [route])

  useEffect(() => {
    document.body.dataset.motion = motionProfile
  }, [motionProfile])

  useEffect(() => {
    document.body.dataset.guide = guideMode === 'off' ? 'off' : 'on'
  }, [guideMode])

  const page = useMemo(() => {
    switch (route) {
      case 'atlas': return <Atlas />
      case 'time': return <TimeLab />
      case 'symbiosis': return <Symbiosis />
      case 'story': return <EcoStory />
      default: return <Prologue />
    }
  }, [route])

  return (
    <MascotGuideController>
      <div className="site-shell">
      <a className="skip-link" href="#main-content">跳到主要内容</a>
      <SiteNav
        active={route}
        guideMode={guideMode}
        onGuideEnable={() => setGuidePreference('on')}
        onGuideSkip={() => setGuidePreference('off')}
        onGuideToggle={() => setGuidePreference(guideMode === 'on' ? 'off' : 'on')}
      />
      <div className="route-curtain" key={route} aria-hidden="true">
        <i />
        <span>{routes.find((item) => item.key === route)?.number}</span>
        <strong>{routes.find((item) => item.key === route)?.zh}</strong>
      </div>
      <main id="main-content" tabIndex={-1}>{page}</main>
      <EcoGuide route={route} />
      <footer className="site-footer">
        <div>
          <p className="eyebrow">QIANJING · ECOLOGICAL TIME</p>
          <p>让数据成为山水，让时间讲述生态。</p>
        </div>
        <p className="footer-note">竞赛交互原型 · 数据截止至已列明公开来源 · 2026</p>
      </footer>
      </div>
    </MascotGuideController>
  )
}
