import { guizhouTerrain } from '../data/guizhouGeo'

export const TERRAIN_SCENE_WIDTH = 10.8
const middleLatitude = (guizhouTerrain.bounds.minLat + guizhouTerrain.bounds.maxLat) / 2
const longitudeKilometerFactor = Math.cos(middleLatitude * Math.PI / 180)
export const TERRAIN_SCENE_DEPTH = TERRAIN_SCENE_WIDTH
  * (guizhouTerrain.bounds.maxLat - guizhouTerrain.bounds.minLat)
  / ((guizhouTerrain.bounds.maxLon - guizhouTerrain.bounds.minLon) * longitudeKilometerFactor)

export interface GuizhouDemGrid {
  width: number
  height: number
  minimum: number
  maximum: number
  bounds: typeof guizhouTerrain.bounds
  values: Uint16Array
}

export const projectLngLat = (longitude: number, latitude: number) => {
  const x = (longitude - guizhouTerrain.bounds.minLon)
    / (guizhouTerrain.bounds.maxLon - guizhouTerrain.bounds.minLon)
    * TERRAIN_SCENE_WIDTH - TERRAIN_SCENE_WIDTH / 2
  const z = (guizhouTerrain.bounds.maxLat - latitude)
    / (guizhouTerrain.bounds.maxLat - guizhouTerrain.bounds.minLat)
    * TERRAIN_SCENE_DEPTH - TERRAIN_SCENE_DEPTH / 2
  return { x, z }
}

export const normalizedHeightToScene = (value: number) => -.9 + value * 3.45

export const decodeElevation = (encoded: number, grid: GuizhouDemGrid) => {
  if (encoded === 65535) return null
  return grid.minimum + encoded / 65534 * (grid.maximum - grid.minimum)
}

export const sampleDem = (grid: GuizhouDemGrid, longitude: number, latitude: number) => {
  const u = (longitude - grid.bounds.minLon) / (grid.bounds.maxLon - grid.bounds.minLon) * (grid.width - 1)
  const v = (grid.bounds.maxLat - latitude) / (grid.bounds.maxLat - grid.bounds.minLat) * (grid.height - 1)
  const x0 = Math.max(0, Math.min(grid.width - 1, Math.floor(u)))
  const y0 = Math.max(0, Math.min(grid.height - 1, Math.floor(v)))
  const x1 = Math.min(grid.width - 1, x0 + 1)
  const y1 = Math.min(grid.height - 1, y0 + 1)
  const samples = [
    { value: decodeElevation(grid.values[y0 * grid.width + x0], grid), weight: (1 - (u - x0)) * (1 - (v - y0)) },
    { value: decodeElevation(grid.values[y0 * grid.width + x1], grid), weight: (u - x0) * (1 - (v - y0)) },
    { value: decodeElevation(grid.values[y1 * grid.width + x0], grid), weight: (1 - (u - x0)) * (v - y0) },
    { value: decodeElevation(grid.values[y1 * grid.width + x1], grid), weight: (u - x0) * (v - y0) },
  ].filter((sample): sample is { value: number; weight: number } => sample.value !== null)
  if (!samples.length) return grid.minimum
  const totalWeight = samples.reduce((sum, sample) => sum + sample.weight, 0)
  return samples.reduce((sum, sample) => sum + sample.value * sample.weight, 0) / Math.max(.0001, totalWeight)
}

export const elevationToScene = (elevation: number, grid: GuizhouDemGrid) =>
  normalizedHeightToScene((elevation - grid.minimum) / Math.max(1, grid.maximum - grid.minimum))

export async function loadGuizhouDem(signal?: AbortSignal): Promise<GuizhouDemGrid> {
  const response = await fetch('/data/guizhou-dem.bin', { signal })
  if (!response.ok) throw new Error(`DEM ${response.status}`)
  const buffer = await response.arrayBuffer()
  const view = new DataView(buffer)
  const magic = String.fromCharCode(...new Uint8Array(buffer, 0, 4))
  if (magic !== 'QJDM' || view.getUint16(4, true) !== 1) throw new Error('Unsupported DEM asset')
  const width = view.getUint16(6, true)
  const height = view.getUint16(8, true)
  const minimum = view.getUint16(10, true)
  const bounds = {
    minLon: view.getFloat32(12, true),
    maxLon: view.getFloat32(16, true),
    minLat: view.getFloat32(20, true),
    maxLat: view.getFloat32(24, true),
  }
  const maximum = view.getUint16(28, true)
  const values = new Uint16Array(buffer, 30, width * height)
  return { width, height, minimum, maximum, bounds, values }
}

export const visibleParticleCount = (grid: GuizhouDemGrid, stride: number) => {
  let count = 0
  for (let row = 0; row < grid.height; row += stride) {
    for (let column = 0; column < grid.width; column += stride) {
      if (grid.values[row * grid.width + column] !== 65535) count += 1
    }
  }
  return count
}

