import terrainMetadata from './guizhou-terrain.json'
import cityCoordinates from './guizhou-cities.json'
import type { CityKey } from './ecology'

export interface GuizhouCityGeo {
  city: CityKey
  nameEn: string
  code: string
  latitude: number
  longitude: number
  geonameId: number
  featureCode: string
  labelOffset: [number, number]
}

export interface GuizhouTerrainMetadata {
  schemaVersion: string
  crs: 'EPSG:4326'
  projectionRuntime: string
  bounds: { minLon: number; maxLon: number; minLat: number; maxLat: number }
  grid: { width: number; height: number }
  elevationMeters: { minimum: number; maximum: number }
  heightVisualExaggeration: number
  validSamples: number
  boundary: [number, number][]
  disclaimer: string
}

export const guizhouTerrain = terrainMetadata as unknown as GuizhouTerrainMetadata

// GeoNames populated-place records (WGS84 / EPSG:4326). These are city data
// indices, not the coordinates of individual air-quality monitoring stations.
export const guizhouCities = cityCoordinates as unknown as GuizhouCityGeo[]

export const getCityGeo = (city: CityKey) => guizhouCities.find((item) => item.city === city)!

