import { useCallback, useEffect, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent, type RefObject } from 'react'

export interface PetPosition { x: number; y: number }
export type PetEdge = 'left' | 'right'

const storageKey = 'qianjing-qianling-position-v1'
const margin = 10

const viewportBounds = (width: number, height: number) => ({
  minX: margin,
  maxX: Math.max(margin, window.innerWidth - width - margin),
  minY: window.innerWidth <= 820 ? 72 : 82,
  maxY: Math.max(82, window.innerHeight - height - margin),
})

export function clampPetPosition(position: PetPosition, width: number, height: number): PetPosition {
  const bounds = viewportBounds(width, height)
  return {
    x: Math.min(bounds.maxX, Math.max(bounds.minX, position.x)),
    y: Math.min(bounds.maxY, Math.max(bounds.minY, position.y)),
  }
}

export function snapPetPosition(position: PetPosition, width: number, height: number): { position: PetPosition; edge: PetEdge } {
  const clamped = clampPetPosition(position, width, height)
  const edge: PetEdge = clamped.x + width / 2 < window.innerWidth / 2 ? 'left' : 'right'
  return {
    position: { ...clamped, x: edge === 'left' ? margin : Math.max(margin, window.innerWidth - width - margin) },
    edge,
  }
}

interface StoredPosition { xRatio: number; yRatio: number; edge: PetEdge }

const readStoredPosition = (): { position: PetPosition; edge: PetEdge } | null => {
  try {
    const stored = JSON.parse(window.localStorage.getItem(storageKey) ?? '') as StoredPosition
    if (!Number.isFinite(stored.xRatio) || !Number.isFinite(stored.yRatio) || !['left', 'right'].includes(stored.edge)) return null
    return {
      position: { x: stored.xRatio * window.innerWidth, y: stored.yRatio * window.innerHeight },
      edge: stored.edge,
    }
  } catch {
    return null
  }
}

export function useDraggablePet(petRef: RefObject<HTMLElement | null>) {
  const stored = useRef(readStoredPosition())
  const [position, setPosition] = useState<PetPosition | null>(stored.current?.position ?? null)
  const [edge, setEdge] = useState<PetEdge>(stored.current?.edge ?? 'right')
  const [dragging, setDragging] = useState(false)
  const [snapping, setSnapping] = useState(false)
  const dragRef = useRef<{ pointerId: number; originX: number; originY: number; startX: number; startY: number; width: number; height: number } | null>(null)
  const suppressClickRef = useRef(false)
  const snapTimerRef = useRef<number | null>(null)

  const persist = useCallback((next: PetPosition, nextEdge: PetEdge) => {
    window.localStorage.setItem(storageKey, JSON.stringify({
      xRatio: next.x / Math.max(1, window.innerWidth),
      yRatio: next.y / Math.max(1, window.innerHeight),
      edge: nextEdge,
    } satisfies StoredPosition))
  }, [])

  const currentRect = useCallback(() => petRef.current?.getBoundingClientRect(), [petRef])

  const onPointerDown = useCallback((event: ReactPointerEvent<HTMLButtonElement>) => {
    if (event.button !== 0) return
    const rect = currentRect()
    if (!rect) return
    event.currentTarget.setPointerCapture(event.pointerId)
    dragRef.current = {
      pointerId: event.pointerId,
      originX: event.clientX,
      originY: event.clientY,
      startX: rect.left,
      startY: rect.top,
      width: rect.width,
      height: rect.height,
    }
    suppressClickRef.current = false
  }, [currentRect])

  const onPointerMove = useCallback((event: ReactPointerEvent<HTMLButtonElement>) => {
    const drag = dragRef.current
    if (!drag || drag.pointerId !== event.pointerId) return
    const dx = event.clientX - drag.originX
    const dy = event.clientY - drag.originY
    if (!dragging && Math.hypot(dx, dy) < 5) return
    event.preventDefault()
    suppressClickRef.current = true
    setDragging(true)
    const next = clampPetPosition({ x: drag.startX + dx, y: drag.startY + dy }, drag.width, drag.height)
    setPosition(next)
    setEdge(next.x + drag.width / 2 < window.innerWidth / 2 ? 'left' : 'right')
  }, [dragging])

  const endDrag = useCallback((event: ReactPointerEvent<HTMLButtonElement>) => {
    const drag = dragRef.current
    if (!drag || drag.pointerId !== event.pointerId) return
    dragRef.current = null
    if (!suppressClickRef.current) return
    const snapped = snapPetPosition({
      x: drag.startX + event.clientX - drag.originX,
      y: drag.startY + event.clientY - drag.originY,
    }, drag.width, drag.height)
    setDragging(false)
    setSnapping(true)
    setPosition(snapped.position)
    setEdge(snapped.edge)
    persist(snapped.position, snapped.edge)
    if (snapTimerRef.current !== null) window.clearTimeout(snapTimerRef.current)
    snapTimerRef.current = window.setTimeout(() => setSnapping(false), 320)
  }, [persist])

  const consumeSuppressedClick = useCallback(() => {
    if (!suppressClickRef.current) return false
    suppressClickRef.current = false
    return true
  }, [])

  const moveByKeyboard = useCallback((event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) return false
    event.preventDefault()
    const rect = currentRect()
    if (!rect) return true
    const step = event.shiftKey ? 32 : 14
    const next = clampPetPosition({
      x: rect.left + (event.key === 'ArrowLeft' ? -step : event.key === 'ArrowRight' ? step : 0),
      y: rect.top + (event.key === 'ArrowUp' ? -step : event.key === 'ArrowDown' ? step : 0),
    }, rect.width, rect.height)
    const nextEdge: PetEdge = next.x + rect.width / 2 < window.innerWidth / 2 ? 'left' : 'right'
    setPosition(next)
    setEdge(nextEdge)
    persist(next, nextEdge)
    return true
  }, [currentRect, persist])

  const resetPosition = useCallback(() => {
    window.localStorage.removeItem(storageKey)
    setPosition(null)
    setEdge('right')
    setDragging(false)
  }, [])

  useEffect(() => {
    const onResize = () => {
      const rect = currentRect()
      if (!rect || !position) return
      const next = clampPetPosition(position, rect.width, rect.height)
      setPosition(next)
      persist(next, edge)
    }
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
  }, [currentRect, edge, persist, position])

  useEffect(() => () => {
    if (snapTimerRef.current !== null) window.clearTimeout(snapTimerRef.current)
  }, [])

  const style: CSSProperties | undefined = position ? { left: position.x, top: position.y, right: 'auto', bottom: 'auto' } : undefined

  return {
    style, edge, dragging, snapping, resetPosition, consumeSuppressedClick, moveByKeyboard,
    pointerHandlers: { onPointerDown, onPointerMove, onPointerUp: endDrag, onPointerCancel: endDrag },
  }
}
