import type { RouteKey } from '../App'
import { routes } from '../App'
import { MountainWaterMark } from './ContourField'
import { InteractionGuide, type GuideMode } from './InteractionGuide'

export function SiteNav({ active, guideMode, onGuideEnable, onGuideSkip, onGuideToggle }: {
  active: RouteKey
  guideMode: GuideMode
  onGuideEnable: () => void
  onGuideSkip: () => void
  onGuideToggle: () => void
}) {
  return (
    <header className="site-nav">
      <a href="#/prologue" className="brand" aria-label="返回山水序章">
        <span className="brand-mark"><MountainWaterMark /></span>
        <span className="brand-copy">
          <strong>黔境·生态时光</strong>
          <small>QIANJING · ECOLOGICAL TIME</small>
        </span>
      </a>
      <nav aria-label="主导航">
        {routes.map((item) => (
          <a
            key={item.key}
            href={`#/${item.key}`}
            className={active === item.key ? 'is-active' : ''}
            aria-current={active === item.key ? 'page' : undefined}
          >
            <span>{item.number}</span>
            <strong>{item.zh}</strong>
          </a>
        ))}
      </nav>
      <div className="nav-tools">
        <button type="button" className={`interaction-guide-toggle ${guideMode === 'on' ? 'is-active' : ''}`} aria-pressed={guideMode === 'on'} onClick={onGuideToggle}>
          <span aria-hidden="true">⌖</span>交互指引
        </button>
        <span className="nav-status"><i /> <b>{routes.findIndex((item) => item.key === active) + 1}</b> / 5 · 数据展览</span>
        <InteractionGuide route={active} mode={guideMode} onEnable={onGuideEnable} onSkip={onGuideSkip} onToggle={onGuideToggle} />
      </div>
    </header>
  )
}
