import type { KnowledgeEntry } from '../../data/qianling-knowledge'
import type { GuideMessage } from './guideMessages'
import { resolveMessageSources } from './guideMessages'
import { MascotKnowledgeCard, MascotQuestionList } from './MascotKnowledgeCard'

export function MascotDialogue({
  message, activeKnowledge, onKnowledge, onBack, onClose, onHide, onResetPosition,
}: {
  message: GuideMessage
  activeKnowledge: KnowledgeEntry | null
  onKnowledge: (entry: KnowledgeEntry) => void
  onBack: () => void
  onClose: () => void
  onHide: () => void
  onResetPosition: () => void
}) {
  const sources = resolveMessageSources(message)
  return (
    <div id="qianling-dialogue" className="qianling-dialogue" role="dialog" aria-label="黔小灵生态知识面板">
      <header>
        <p><span>QIANLING</span><i /> GUIZHOU ECO GUIDE</p>
        <div><button type="button" onClick={onResetPosition} aria-label="重置黔小灵位置">↺</button><button type="button" onClick={onHide} aria-label="暂时隐藏黔小灵">—</button><button type="button" onClick={onClose} aria-label="关闭黔小灵知识面板">×</button></div>
      </header>
      {activeKnowledge ? <MascotKnowledgeCard entry={activeKnowledge} onBack={onBack} /> : (
        <>
          <section className="qianling-page-tip">
            <p>{message.eyebrow}</p>
            <h2>{message.title}</h2>
            <div>{message.text}</div>
            {message.action?.href && <a href={message.action.href}>{message.action.label} ↗</a>}
            {message.action?.targetId && (
              <button type="button" className="qianling-tip-action" onClick={() => document.getElementById(message.action?.targetId ?? '')?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' })}>
                {message.action.label} ↗
              </button>
            )}
            {sources.length > 0 && <footer>{sources.map((source) => <a key={source.id} href={source.url} target="_blank" rel="noreferrer">{source.publisher} ↗</a>)}</footer>}
          </section>
          <MascotQuestionList onSelect={onKnowledge} />
        </>
      )}
    </div>
  )
}
