import type { AirPeriod } from '../data/ecology'

const years = Array.from({ length: 10 }, (_, index) => 2016 + index)

export function TemporalDecadeControl({ periods, activeIndex, playing, disabled, onChange, onTogglePlay }: {
  periods: AirPeriod[]
  activeIndex: number
  playing: boolean
  disabled?: boolean
  onChange: (index: number) => void
  onTogglePlay: () => void
}) {
  const active = periods[activeIndex]
  const availableYears = new Set(periods.map((period) => Number(period.id.slice(0, 4))))
  const selectYear = (year: number) => {
    const index = periods.reduce((found, period, periodIndex) => Number(period.id.slice(0, 4)) === year ? periodIndex : found, -1)
    if (index >= 0) onChange(index)
  }
  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return
    if (event.key === 'ArrowRight') { event.preventDefault(); onChange(Math.min(periods.length - 1, activeIndex + 1)) }
    if (event.key === 'ArrowLeft') { event.preventDefault(); onChange(Math.max(0, activeIndex - 1)) }
    if (event.key === 'Home') { event.preventDefault(); onChange(0) }
    if (event.key === 'End') { event.preventDefault(); onChange(periods.length - 1) }
  }

  return (
    <div className={`temporal-decade ${disabled ? 'is-disabled' : ''}`} data-guide-target="time-axis">
      <div className="temporal-transport">
        <button type="button" onClick={onTogglePlay} disabled={disabled} aria-pressed={playing}>
          <span>{playing ? 'Ⅱ' : '▶'}</span>{playing ? 'PAUSE / 暂停' : 'PLAY VERIFIED NODES / 播放已核实节点'}
        </button>
        <output aria-live="polite"><small>ACTIVE NODE</small><strong>{active.shortLabel}</strong></output>
        <p>2016—2025 DECADE ARCHIVE <i /> 仅开放有官方数据的年份</p>
      </div>
      <div className="decade-track" role="slider" tabIndex={disabled ? -1 : 0} aria-label="2016至2025十年时间轴" aria-valuemin={2016} aria-valuemax={2025} aria-valuenow={Number(active.id.slice(0, 4))} aria-valuetext={active.label} onKeyDown={onKeyDown}>
        <span className="decade-line" aria-hidden="true" />
        {years.map((year) => {
          const available = availableYears.has(year)
          const activeYear = active.id.startsWith(String(year))
          return (
            <button key={year} type="button" disabled={!available || disabled} className={`${available ? 'has-data' : 'is-missing'} ${activeYear ? 'is-active' : ''}`} onClick={() => selectYear(year)} aria-label={available ? `${year}年，有已核实数据` : `${year}年，暂无已核实数据`}>
              <i /><span>{year}</span>{!available && <small>—</small>}
            </button>
          )
        })}
      </div>
      <div className="verified-node-row" aria-label="已核实的时间节点">
        {periods.map((period, index) => <button type="button" key={period.id} disabled={disabled} className={index === activeIndex ? 'is-active' : ''} onClick={() => onChange(index)}>{period.shortLabel}</button>)}
      </div>
    </div>
  )
}
