import { useRef, useState, type CSSProperties } from 'react'
import type { AirCityRecord, AirMetric, AnnualAirPeriod, CityKey } from '../data/ecology'
import { metricLabel } from '../data/ecology'
import { ChartExportButton } from './ChartExportButton'

interface CommonProps {
  records: AirCityRecord[]
  metric: AirMetric
  selected: CityKey
  onSelect: (city: CityKey) => void
}

export function SchematicMap({ records, metric, selected, onSelect }: CommonProps) {
  const [hovered, setHovered] = useState<CityKey | null>(null)
  const active = records.find((item) => item.city === (hovered ?? selected)) ?? records[0]
  const values = records.map((item) => item[metric])
  const min = Math.min(...values)
  const max = Math.max(...values)
  const radius = (value: number) => 2.6 + ((value - min) / Math.max(1, max - min)) * 4.4

  return (
    <div className="schematic-map">
      <div className="map-caption">
        <span>贵州九城空间示意</span>
        <small>原创空间关系图，不代表行政边界</small>
      </div>
      <svg viewBox="0 0 100 100" role="img" aria-label={`${metricLabel[metric]}九城空间示意图`}>
        <defs>
          <linearGradient id="mapFill" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#83C8AB" stopOpacity=".15" />
            <stop offset="1" stopColor="#86BFCF" stopOpacity=".03" />
          </linearGradient>
          <filter id="glow"><feGaussianBlur stdDeviation="1.7" /></filter>
        </defs>
        <path className="schematic-outline" d="M18 18L39 13L55 19L68 15L84 31L79 46L86 60L69 68L64 85L45 89L35 80L18 84L14 67L8 54L16 42L12 30Z" />
        <g className="map-contours">
          <path d="M17 29c14-12 36-14 52-4 14 8 21 22 15 32-7 11-27 8-38 18-10 9-9 15-24 11" />
          <path d="M22 34c13-9 29-10 41-3 11 6 17 16 12 23-5 8-20 7-29 14-8 6-9 11-19 10" />
          <path d="M28 40c10-6 21-6 29-2 8 4 11 11 7 16-4 5-14 5-21 10-5 4-6 7-12 7" />
        </g>
        <path className="map-flow" d="M50 20C45 36 60 40 50 53S47 72 58 86" />
        {records.map((item) => {
          const isActive = item.city === selected
          return (
            <g
              key={item.city}
              className={`map-marker ${isActive ? 'is-active' : ''}`}
              role="button"
              tabIndex={0}
              aria-label={`${item.city} ${metricLabel[metric]} ${item[metric]}微克每立方米`}
              onClick={() => onSelect(item.city)}
              onMouseEnter={() => setHovered(item.city)}
              onMouseLeave={() => setHovered(null)}
              onFocus={() => setHovered(item.city)}
              onBlur={() => setHovered(null)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault()
                  onSelect(item.city)
                }
              }}
            >
              <circle className="marker-glow" cx={item.x} cy={item.y} r={radius(item[metric]) + 2} filter="url(#glow)" />
              <circle className="marker-ring" cx={item.x} cy={item.y} r={radius(item[metric]) + 4.5} />
              <circle className="marker-core" cx={item.x} cy={item.y} r={radius(item[metric])} />
              <text x={item.x} y={item.y + 10} textAnchor="middle">{item.city.replace('市', '')}</text>
            </g>
          )
        })}
      </svg>
      <div className="map-tooltip" aria-live="polite">
        <span>{active.city}</span>
        <strong>{active[metric]}</strong>
        <small>μg/m³ · {metricLabel[metric]}</small>
      </div>
      <div className="map-legend" aria-hidden="true"><span>LOW</span><i /><i /><i /><span>HIGH</span></div>
    </div>
  )
}

export function AirBars({ records, metric, selected, onSelect, caption = 'MONTHLY CONCENTRATION · μg/m³', frequencyLabel = '月均' }: CommonProps & { caption?: string; frequencyLabel?: '月均' | '年均' }) {
  const [hovered, setHovered] = useState<CityKey | null>(null)
  const chartRef = useRef<HTMLDivElement>(null)
  if (!records.length) {
    return <div className="chart-missing"><i />暂无可核验数据</div>
  }
  const max = Math.max(...records.map((item) => item[metric]))
  const axisMax = Math.ceil(max / 10) * 10
  const ticks = [axisMax, axisMax * .75, axisMax * .5, axisMax * .25, 0]
  const active = records.find((item) => item.city === (hovered ?? selected)) ?? records[0]
  const activeIndex = Math.max(0, records.findIndex((item) => item.city === active.city))
  const crosshairStyle = {
    '--cross-x': `${(activeIndex + .5) / records.length * 100}%`,
    '--cross-y': `${100 - active[metric] / axisMax * 100}%`,
  } as CSSProperties
  return (
    <div className="air-chart-shell eco-hud-module" ref={chartRef}>
      <div className="chart-head">
        <div className="eco-chart-title">
          <span>01</span>
          <p><strong>九城空气质量</strong><small>NINE-CITY AIR QUALITY · {metricLabel[metric]}</small></p>
          <i />
        </div>
        <div className="chart-head-actions">
          <output aria-live="polite"><span>ACTIVE / {active.city.replace('市', '')}</span><strong>{active[metric]}</strong><small>μg/m³</small></output>
          <ChartExportButton targetRef={chartRef} filename={`黔境-${metricLabel[metric]}-${caption.split('·')[0].trim()}`} />
        </div>
      </div>
      <div className="chart-body">
        <span className="eco-axis-unit">{metricLabel[metric]} · μg/m³</span>
        <div className="chart-axis" aria-hidden="true">{ticks.map((tick) => <span key={tick}>{tick}</span>)}</div>
        <div className="chart-grid" aria-hidden="true">{ticks.map((tick) => <i key={tick} />)}</div>
        <div className="air-bars" role="list" aria-label={`${metricLabel[metric]}城市对比`} style={crosshairStyle}>
          <div className="eco-chart-crosshair" aria-hidden="true"><i /><b /></div>
          <output className="eco-bar-tooltip" aria-live="polite" aria-hidden={!hovered}>
            <span>{active.city} · {metricLabel[metric]}</span><strong>{active[metric]}</strong><small>μg/m³ · 城市{frequencyLabel}浓度</small>
          </output>
          {records.map((item, index) => (
            <button
              key={item.city}
              type="button"
              role="listitem"
              className={item.city === selected ? 'is-active' : ''}
              onClick={() => onSelect(item.city)}
              onMouseEnter={() => setHovered(item.city)}
              onMouseLeave={() => setHovered(null)}
              onFocus={() => setHovered(item.city)}
              onBlur={() => setHovered(null)}
              aria-label={`${item.city}：${item[metric]}微克每立方米`}
              aria-pressed={item.city === selected}
            >
              <span className="bar-value"><b>{item[metric]}</b><i>NODE {String(index + 1).padStart(2, '0')}</i></span>
              <span className="bar-track"><i style={{ height: `${Math.max(8, item[metric] / axisMax * 100)}%` }}><b /></i></span>
              <span className="bar-city"><i>{String(index + 1).padStart(2, '0')}</i>{item.city.replace('市', '')}</span>
            </button>
          ))}
        </div>
      </div>
      <div className="chart-foot"><span>STAT / CITY {frequencyLabel === '年均' ? 'ANNUAL' : 'MONTHLY'} · {caption}</span><span><i /> 当前选中 <em /> 已核实城市值 <b /> 缺失节点</span></div>
    </div>
  )
}

interface AirArchiveMatrixProps {
  periods: AnnualAirPeriod[]
  metric: AirMetric
  selected: CityKey
  selectedYear: number
  onSelect: (city: CityKey) => void
  onYearChange: (year: number) => void
}

const archiveYears = Array.from({ length: 10 }, (_, index) => 2016 + index)

function getArchiveRank(records: AnnualAirPeriod['records'], city: CityKey, metric: AirMetric) {
  const value = records.find((record) => record.city === city)?.[metric]
  if (value === null || value === undefined) return null
  return 1 + records.filter((record) => record[metric] !== null && record[metric]! < value).length
}

function buildArchiveTrend(periods: AnnualAirPeriod[], city: CityKey, metric: AirMetric) {
  const values = archiveYears.map((year) => periods.find((period) => period.year === year)?.records.find((record) => record.city === city)?.[metric] ?? null)
  const numericValues = values.filter((value): value is number => value !== null)
  const min = Math.min(...numericValues)
  const max = Math.max(...numericValues)
  const spread = Math.max(1, max - min)
  const points = values.map((value, index) => value === null ? null : {
    year: archiveYears[index],
    value,
    x: 4 + index / (archiveYears.length - 1) * 92,
    y: 28 - (value - min) / spread * 22,
  })
  const segments: Array<Array<NonNullable<(typeof points)[number]>>> = []
  let activeSegment: Array<NonNullable<(typeof points)[number]>> = []
  points.forEach((point) => {
    if (point) {
      activeSegment.push(point)
      return
    }
    if (activeSegment.length) segments.push(activeSegment)
    activeSegment = []
  })
  if (activeSegment.length) segments.push(activeSegment)
  return { points, segments }
}

export function AirArchiveMatrix({ periods, metric, selected, selectedYear, onSelect, onYearChange }: AirArchiveMatrixProps) {
  const chartRef = useRef<HTMLDivElement>(null)
  const availablePeriods = periods.filter((period) => period.records.length === 9 && period.records.every((record) => record[metric] !== null))
  const activePeriod = availablePeriods.find((period) => period.year === selectedYear) ?? availablePeriods[availablePeriods.length - 1]

  if (!activePeriod) {
    return <div className="chart-missing"><i />暂无可逐城核验的{metricLabel[metric]}年度数据</div>
  }

  const records = activePeriod.records.filter((record) => record[metric] !== null)
  const values = records.map((record) => record[metric] as number)
  const lowRecord = records.reduce((lowest, record) => (record[metric] as number) < (lowest[metric] as number) ? record : lowest)
  const highRecord = records.reduce((highest, record) => (record[metric] as number) > (highest[metric] as number) ? record : highest)
  const selectedRecord = records.find((record) => record.city === selected) ?? records[0]
  const selectedValue = selectedRecord[metric] as number
  const scaleMax = Math.max(10, Math.ceil(Math.max(...availablePeriods.flatMap((period) => period.records.map((record) => record[metric] ?? 0))) / 10) * 10)
  const average = activePeriod.publishedAverage[metric] ?? values.reduce((sum, value) => sum + value, 0) / values.length

  return (
    <div className="air-archive-matrix eco-hud-module" ref={chartRef}>
      <div className="archive-matrix-head">
        <div className="eco-chart-title">
          <span>01</span>
          <p><strong>九城空气年度档案</strong><small>NINE-CITY AIR ARCHIVE · {metricLabel[metric]}</small></p>
          <i />
        </div>
        <div className="archive-head-actions">
          <output aria-live="polite"><span>ACTIVE / {selectedRecord.city.replace('市', '')}</span><strong>{selectedValue}</strong><small>μg/m³</small></output>
          <ChartExportButton targetRef={chartRef} filename={`黔境-${activePeriod.year}年-${metricLabel[metric]}-九城年度档案`} />
        </div>
      </div>

      <div className="archive-year-control" aria-label={`${metricLabel[metric]}年度选择`}>
        <div className="archive-year-label">
          <span>YEAR INDEX / 年份索引</span>
          <strong>{activePeriod.year}</strong>
          <small>仅开放九城逐项核实数据</small>
        </div>
        <div className="archive-year-rail">
          {archiveYears.map((year) => {
            const available = availablePeriods.some((period) => period.year === year)
            return (
              <button
                type="button"
                key={year}
                disabled={!available}
                className={activePeriod.year === year ? 'is-active' : available ? 'has-data' : 'is-missing'}
                onClick={() => onYearChange(year)}
                aria-label={available ? `${year}年，有已核实${metricLabel[metric]}年度数据` : `${year}年，暂无可逐城核验的${metricLabel[metric]}年度数据`}
              >
                <span>{year}</span><i />
              </button>
            )
          })}
        </div>
      </div>

      <div className="archive-summary" aria-label={`${activePeriod.year}年九城${metricLabel[metric]}摘要`}>
        <div><span>九城平均</span><strong>{average.toFixed(1)}</strong><small>μg/m³</small></div>
        <div><span>最低城市</span><strong>{lowRecord.city.replace('市', '')}</strong><small>{lowRecord[metric]} μg/m³</small></div>
        <div><span>最高城市</span><strong>{highRecord.city.replace('市', '')}</strong><small>{highRecord[metric]} μg/m³</small></div>
      </div>

      <div className="archive-city-grid" role="list" aria-label={`${activePeriod.year}年九城${metricLabel[metric]}年均浓度`}>
        {records.map((record, index) => {
          const value = record[metric] as number
          const rank = getArchiveRank(activePeriod.records, record.city, metric)
          const progress = Math.min(100, value / scaleMax * 100)
          const trend = buildArchiveTrend(periods, record.city, metric)
          const active = record.city === selected
          return (
            <div className="archive-city-item" role="listitem" key={record.city}>
              <button
                type="button"
                className={`archive-city-card ${active ? 'is-active' : ''}`}
                onClick={() => onSelect(record.city)}
                aria-pressed={active}
                aria-label={`${record.city}，${activePeriod.year}年${metricLabel[metric]}年均浓度${value}微克每立方米，九城低值序位第${rank}`}
              >
              <span className="archive-card-head"><span><strong>{record.city.replace('市', '')}</strong><small>CITY {String(index + 1).padStart(2, '0')}</small></span><em>VERIFIED</em></span>
              <span className="archive-card-body">
                <span className="archive-value-ring">
                  <svg viewBox="0 0 110 110" aria-hidden="true">
                    <circle className="archive-ring-track" cx="55" cy="55" r="46" pathLength="100" />
                    <circle className="archive-ring-value" cx="55" cy="55" r="46" pathLength="100" strokeDasharray={`${progress} ${100 - progress}`} />
                  </svg>
                  <span><strong>{value}</strong><small>μg/m³</small></span>
                </span>
                <span className="archive-card-detail">
                  <span><small>低值序位</small><strong>{String(rank).padStart(2, '0')} / 09</strong></span>
                  <span><small>统计年份</small><strong>{activePeriod.year}</strong></span>
                  <span><small>统计频率</small><strong>ANNUAL</strong></span>
                  <span className="archive-mini-trend">
                    <svg viewBox="0 0 100 34" role="img" aria-label={`${record.city}${metricLabel[metric]}2016至2025年已核实年度节点`}>
                      {trend.segments.filter((segment) => segment.length > 1).map((segment, segmentIndex) => (
                        <polyline key={segmentIndex} points={segment.map((point) => `${point.x},${point.y}`).join(' ')} />
                      ))}
                      {trend.points.map((point) => point && (
                        <circle key={point.year} className={point.year === activePeriod.year ? 'is-current' : ''} cx={point.x} cy={point.y} r={point.year === activePeriod.year ? 2.5 : 1.6} />
                      ))}
                    </svg>
                      <small><span>2016</span><span>缺失断点</span><span>2025</span></small>
                  </span>
                </span>
              </span>
              </button>
            </div>
          )
        })}
      </div>

      <div className="archive-matrix-foot">
        <span>STAT / CITY ANNUAL · {activePeriod.label} · 九城年均 · μg/m³</span>
        <span><i /> 当前选中 <em /> 已核实节点 <b /> 缺失年份不连线</span>
      </div>
    </div>
  )
}

export function MetricToggle({ metric, onChange }: { metric: AirMetric; onChange: (value: AirMetric) => void }) {
  return (
    <div className="segmented-control" aria-label="选择空气指标" data-guide-target="metric-toggle">
      {(['pm25', 'pm10'] as AirMetric[]).map((key) => (
        <button
          type="button"
          key={key}
          className={metric === key ? 'is-active' : ''}
          onClick={() => onChange(key)}
          aria-pressed={metric === key}
        >
          {metricLabel[key]}
        </button>
      ))}
    </div>
  )
}
