import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { LazyTriadEcoCore } from '../components/LazyTriadEcoCore'
import type { EcoDomain } from '../components/TriadEcoCore'
import { useMascotGuideController } from '../components/qianling/MascotGuideController'
import { airPeriods, datasetSummary, forestEvidence, getAverage, getSource, waterEvidence } from '../data/ecology'
import { useMotionProfile } from '../hooks/useMotionProfile'

const wakeSessionKey = 'qianjing-triad-awakened-v1'

const wakeLabels = [
  '生命舱待机',
  '生态核心上电',
  '空气粒子接入',
  '水流光路接入',
  '森林点云接入',
  '三域共振完成',
]

export function Prologue() {
  const { publishPageContext } = useMascotGuideController()
  const motionProfile = useMotionProfile()
  const [domain, setDomain] = useState<EcoDomain>('air')
  const [wakeStage, setWakeStage] = useState(() => window.sessionStorage.getItem(wakeSessionKey) ? 5 : 0)
  const [initializing, setInitializing] = useState(false)
  const [resetViewSignal, setResetViewSignal] = useState(0)
  const timers = useRef<number[]>([])

  const latestAir = airPeriods[airPeriods.length - 1]
  const annualWater = waterEvidence.find((item) => item.temporalResolution === 'year')
  const latestForest = forestEvidence[forestEvidence.length - 1]
  const airAverage = getAverage(latestAir, 'pm25') ?? 0

  const themes = useMemo(() => ([
    {
      id: 'air' as const,
      index: 'A-01',
      en: 'AIR',
      zh: '空气',
      title: '山城之息',
      value: airAverage.toFixed(0),
      unit: 'μg/m³',
      metric: '九城 PM2.5 月平均浓度',
      period: latestAir.label,
      scope: latestAir.scope,
      sourceId: latestAir.sourceId,
      action: '进入城市空气监测',
      href: '#/atlas',
      caution: '城市月度指标；不代表贵州全域实时空气状态。',
    },
    {
      id: 'water' as const,
      index: 'W-02',
      en: 'WATER',
      zh: '水环境',
      title: '江河之脉',
      value: String(annualWater?.value ?? '—'),
      unit: annualWater?.unit ?? '',
      metric: annualWater?.label ?? '主要河流出境断面水质优良率',
      period: annualWater?.period ?? '暂无数据',
      scope: annualWater?.scope ?? '贵州省｜统计范围待核实',
      sourceId: annualWater?.sourceId ?? '',
      action: '探索江河生态',
      href: '#/symbiosis?section=water',
      caution: '省级年度断面指标；不等同于所有河流的实时水质。',
    },
    {
      id: 'forest' as const,
      index: 'F-03',
      en: 'FOREST',
      zh: '森林',
      title: '青山之境',
      value: String(latestForest?.value ?? '—'),
      unit: latestForest?.unit ?? '',
      metric: latestForest?.label ?? '完成营造林面积',
      period: latestForest ? `${latestForest.year}年` : '暂无数据',
      scope: latestForest ? `${latestForest.geography}｜${latestForest.monitoringScope}` : '贵州省｜年度行动记录',
      sourceId: latestForest?.sourceId ?? '',
      action: '探索森林生态',
      href: '#/symbiosis?section=forest',
      caution: '省级年度完成量；不等同于森林覆盖率或森林质量。',
    },
  ]), [airAverage, annualWater, latestAir, latestForest])

  const activeTheme = themes.find((item) => item.id === domain) ?? themes[0]
  const activeSource = getSource(activeTheme.sourceId)
  const sceneDomain: EcoDomain = initializing
    ? wakeStage <= 2 ? 'air' : wakeStage === 3 ? 'water' : wakeStage === 4 ? 'forest' : domain
    : domain

  const clearWakeTimers = useCallback(() => {
    timers.current.forEach((timer) => window.clearTimeout(timer))
    timers.current = []
  }, [])

  const completeWake = useCallback(() => {
    clearWakeTimers()
    setWakeStage(5)
    setInitializing(false)
    window.sessionStorage.setItem(wakeSessionKey, '1')
  }, [clearWakeTimers])

  const initializeEcosystem = () => {
    clearWakeTimers()
    if (motionProfile === 'reduced') {
      completeWake()
      return
    }
    setWakeStage(1)
    setInitializing(true)
    ;[2, 3, 4, 5].forEach((stage, index) => {
      timers.current.push(window.setTimeout(() => setWakeStage(stage), 610 + index * 610))
    })
    timers.current.push(window.setTimeout(completeWake, 3180))
  }

  const selectDomain = (nextDomain: EcoDomain) => {
    if (initializing) return
    setDomain(nextDomain)
    publishPageContext({ route: 'prologue', theme: nextDomain }, { announce: true })
  }

  useEffect(() => {
    publishPageContext({ route: 'prologue' })
  }, [publishPageContext])

  useEffect(() => () => clearWakeTimers(), [clearWakeTimers])

  useEffect(() => {
    if (motionProfile === 'reduced' && wakeStage < 5) completeWake()
  }, [completeWake, motionProfile, wakeStage])

  return (
    <div className={`page prologue-page triad-page triad-page-${domain}`}>
      <section className={`triad-hero ${wakeStage >= 5 ? 'is-awake' : ''} ${initializing ? 'is-initializing' : ''}`}>
        <div className="triad-ambient-grid" aria-hidden="true" />
        <div className="triad-ambient-orbit" aria-hidden="true"><i /><i /><i /></div>

        <div className="triad-shell">
          <header className="triad-copy">
            <p className="triad-system-label"><span>01</span> TRIAD ECO SYSTEM · GUIZHOU</p>
            <h1><span>山水之间</span><strong>万物共振</strong></h1>
            <p className="triad-title-en">THE ECOLOGICAL PULSE<br />OF GUIZHOU</p>
            <p className="triad-lead">一口空气，一条江河，一片青山。<br />以数字感知生态，以时间记录变化。</p>

            <nav className="triad-mode-switcher" aria-label="选择生态主题" data-guide-target="prologue-themes">
              {themes.map((theme) => (
                <button
                  type="button"
                  key={theme.id}
                  className={domain === theme.id ? 'is-active' : ''}
                  aria-pressed={domain === theme.id}
                  disabled={initializing}
                  onClick={() => selectDomain(theme.id)}
                >
                  <span>{theme.index}</span>
                  <i aria-hidden="true" />
                  <strong>{theme.en}</strong>
                  <small>{theme.zh}</small>
                </button>
              ))}
            </nav>

            <div className="triad-primary-actions" data-guide-target="prologue-entry">
              {wakeStage < 5 ? (
                <button type="button" className="triad-initialize" onClick={initializeEcosystem} disabled={initializing}>
                  <span><small>INITIALIZE ECOSYSTEM</small>{initializing ? wakeLabels[wakeStage] : '启动生态探索'}</span>
                  <i aria-hidden="true">{initializing ? `${wakeStage}/5` : '↗'}</i>
                </button>
              ) : (
                <a className="triad-enter-domain" href={activeTheme.href}>
                  <span><small>{activeTheme.en} DOMAIN</small>{activeTheme.action}</span><i aria-hidden="true">↗</i>
                </a>
              )}
              <a className="triad-time-link" href="#/time"><span>03</span> 探索十年生态变化 <i>→</i></a>
            </div>
          </header>

          <div className="triad-stage" data-guide-target="prologue-core">
            <div className="triad-stage-heading">
              <span>ECO LIFE CAPSULE / CTL-01</span>
              <strong>三域生态核心</strong>
              <small>程序化艺术装置 · 非真实贵州地形或遥感影像</small>
            </div>
            <LazyTriadEcoCore domain={sceneDomain} wakeStage={wakeStage} resetViewSignal={resetViewSignal} />
            <div className="triad-corner triad-corner-a" aria-hidden="true" />
            <div className="triad-corner triad-corner-b" aria-hidden="true" />

            <div className="triad-nodes" aria-label="生态信号节点">
              {themes.map((theme) => (
                <button
                  type="button"
                  key={theme.id}
                  className={`triad-node triad-node-${theme.id} ${domain === theme.id ? 'is-active' : ''}`}
                  onClick={() => selectDomain(theme.id)}
                  disabled={initializing}
                  aria-pressed={domain === theme.id}
                >
                  <span>{theme.index}</span><i aria-hidden="true" /><strong>{theme.en}</strong><small>{theme.value} {theme.unit}</small>
                </button>
              ))}
            </div>

            <aside className="triad-signal-readout" aria-live="polite" key={activeTheme.id}>
              <header><span>ACTIVE ECO SIGNAL</span><i /> <strong>{activeTheme.index}</strong></header>
              <p className="triad-signal-title"><small>{activeTheme.en} / {activeTheme.zh}</small><b>{activeTheme.title}</b></p>
              <p className="triad-signal-value"><strong>{activeTheme.value}</strong><span>{activeTheme.unit}</span></p>
              <dl>
                <div><dt>指标</dt><dd>{activeTheme.metric}</dd></div>
                <div><dt>时间</dt><dd>{activeTheme.period}</dd></div>
                <div><dt>范围</dt><dd>{activeTheme.scope}</dd></div>
              </dl>
              <small className="triad-signal-caution">{activeTheme.caution}</small>
            </aside>

            {wakeStage < 5 && (
              <div className="triad-wake-status" aria-live="polite">
                <span>{String(wakeStage).padStart(2, '0')} / 05</span>
                <strong>{wakeLabels[wakeStage]}</strong>
                <div><i style={{ width: `${wakeStage * 20}%` }} /></div>
                {initializing && <button type="button" onClick={completeWake}>跳过启动动画</button>}
              </div>
            )}

            <button type="button" className="triad-reset-view" onClick={() => setResetViewSignal((value) => value + 1)}>
              <span>↺</span> RESET VIEW / 重置视角
            </button>
            <p className="triad-drag-note">DRAG TO ORBIT · SCROLL TO ZOOM</p>
          </div>
        </div>

        <div className="triad-control-rail">
          <span><b>CORE</b> {wakeStage >= 5 ? 'ONLINE' : 'STANDBY'}</span>
          <span><b>MODE</b> {activeTheme.en} / {activeTheme.zh}</span>
          <span><b>EVIDENCE</b> {datasetSummary.sourceCount} PUBLIC RECORDS</span>
          <span><b>VISUAL</b> CONCEPT TERRAIN / NON-GIS</span>
          <span className="triad-rail-signal"><i /> {wakeLabels[wakeStage].toUpperCase()}</span>
        </div>
      </section>

      <section className="triad-evidence" id="triad-evidence">
        <header className="triad-evidence-intro">
          <p>THREE DOMAINS / THREE SCALES</p>
          <h2>同一片山水，<br />三种证据尺度。</h2>
          <div>空气以城市月度数据被观测；水与森林以省级年度口径被记录。这里保留它们的差异，不把三个数值包装成同一条“实时趋势”。</div>
        </header>

        <div className="triad-evidence-ledger">
          {themes.map((theme, index) => {
            const source = getSource(theme.sourceId)
            return (
              <a key={theme.id} href={theme.href} className={`triad-evidence-row triad-evidence-row-${theme.id}`}>
                <span>{String(index + 1).padStart(2, '0')}</span>
                <div><small>{theme.en}</small><strong>{theme.title}</strong></div>
                <p><b>{theme.value}</b><i>{theme.unit}</i></p>
                <dl><div><dt>时间</dt><dd>{theme.period}</dd></div><div><dt>统计范围</dt><dd>{theme.scope}</dd></div><div><dt>来源</dt><dd>{source?.publisher ?? '来源登记待核实'}</dd></div></dl>
                <em>进入主题 ↗</em>
              </a>
            )
          })}
        </div>

        <footer className="triad-evidence-footer">
          <div><span>DATA INTEGRITY / 资料边界</span><p>生态核心中的流动波纹、扫描环与粒子动画是艺术化生态信号，不是连续监测曲线，也不表达未经数据支持的空间分布。</p></div>
          <div><span>ACTIVE SOURCE / 当前来源</span><p>{activeSource?.publisher ?? '来源登记'} · {activeSource?.title ?? activeTheme.metric}</p></div>
          <a href="#/time">ECO TEMPORAL CONTROL <i>→</i><strong>进入时光实验室</strong></a>
        </footer>
      </section>
    </div>
  )
}
