import { getSource } from '../data/ecology'

export function SourcePanel({ sourceIds, title = '数据来源与口径' }: { sourceIds: string[]; title?: string }) {
  const sources = sourceIds.map(getSource).filter(Boolean)
  return (
    <details className="source-panel">
      <summary>
        <span>{title}</span>
        <span aria-hidden="true">展开 ↘</span>
      </summary>
      <div className="source-list">
        {sources.map((source) => source && (
          <article key={source.id}>
            <div>
              <span className="source-period">{source.period} · {source.status === 'verified' ? '已核实' : '已交叉复核'}</span>
              <h3>{source.title}</h3>
            </div>
            <p>{source.scope}</p>
            <p>{source.publisher}<br />{source.note}</p>
            <a href={source.url} target="_blank" rel="noreferrer">查看原始来源 ↗</a>
          </article>
        ))}
      </div>
    </details>
  )
}
