import { qianlingKnowledge, qianlingSources, type KnowledgeEntry } from '../../data/qianling-knowledge'

export function MascotKnowledgeCard({ entry, onBack }: { entry: KnowledgeEntry; onBack: () => void }) {
  return (
    <article className="qianling-knowledge-card" aria-live="polite">
      <button type="button" className="qianling-back" onClick={onBack}>← 返回问题</button>
      <p>VERIFIED KNOWLEDGE</p>
      <h3>{entry.question}</h3>
      <div>{entry.answer}</div>
      <footer>
        <span>资料来源</span>
        {entry.sourceIds.map((id) => {
          const source = qianlingSources[id]
          return <a key={id} href={source.url} target={source.url.startsWith('http') ? '_blank' : undefined} rel="noreferrer">{source.publisher} ↗</a>
        })}
      </footer>
    </article>
  )
}

export function MascotQuestionList({ onSelect }: { onSelect: (entry: KnowledgeEntry) => void }) {
  return (
    <div className="qianling-question-list" aria-label="黔小灵预设知识问答">
      <p>ASK QIANLING / 问问黔小灵</p>
      {qianlingKnowledge.map((entry, index) => (
        <button type="button" key={entry.id} onClick={() => onSelect(entry)}>
          <span>{String(index + 1).padStart(2, '0')}</span>{entry.question}<i>↗</i>
        </button>
      ))}
    </div>
  )
}
