import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from 'react'
import type { AirMetric, CityKey } from '../../data/ecology'

export type GuideRoute = 'prologue' | 'atlas' | 'time' | 'symbiosis' | 'story'
export type PrologueTheme = 'air' | 'water' | 'forest'

export type GuidePageContext =
  | { route: 'prologue'; theme?: PrologueTheme }
  | { route: 'atlas'; city: CityKey; metric: AirMetric; value: number }
  | {
    route: 'time'
    city: CityKey
    metric: AirMetric
    periodLabel: string
    value: number | null
    baselineLabel?: string
    baselineValue?: number
  }
  | { route: 'symbiosis'; section: 'water' | 'forest' }
  | { route: 'story'; act: number; progress: number }

interface GuideControllerValue {
  pageContext: GuidePageContext
  announcementId: number
  publishPageContext: (context: GuidePageContext, options?: { announce?: boolean }) => void
}

const GuideControllerContext = createContext<GuideControllerValue | null>(null)

export function MascotGuideController({ children }: { children: ReactNode }) {
  const [pageContext, setPageContext] = useState<GuidePageContext>({ route: 'prologue' })
  const [announcementId, setAnnouncementId] = useState(0)

  const publishPageContext = useCallback((context: GuidePageContext, options?: { announce?: boolean }) => {
    setPageContext((current) => {
      const currentEntries = Object.entries(current)
      const nextEntries = Object.entries(context)
      const unchanged = currentEntries.length === nextEntries.length
        && nextEntries.every(([key, value]) => current[key as keyof GuidePageContext] === value)
      return unchanged ? current : context
    })
    if (options?.announce) setAnnouncementId((value) => value + 1)
  }, [])

  const value = useMemo(() => ({ pageContext, announcementId, publishPageContext }), [pageContext, announcementId, publishPageContext])
  return <GuideControllerContext.Provider value={value}>{children}</GuideControllerContext.Provider>
}

export function useMascotGuideController() {
  const context = useContext(GuideControllerContext)
  if (!context) throw new Error('useMascotGuideController must be used inside MascotGuideController')
  return context
}
