import { useEffect, useState } from 'react'

export type MotionProfile = 'full' | 'lite' | 'reduced'

const detectMotionProfile = (): MotionProfile => {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return 'reduced'
  const navigatorWithMemory = navigator as Navigator & { deviceMemory?: number }
  const lowMemory = typeof navigatorWithMemory.deviceMemory === 'number' && navigatorWithMemory.deviceMemory <= 4
  const lowConcurrency = typeof navigator.hardwareConcurrency === 'number' && navigator.hardwareConcurrency <= 4
  const compactViewport = window.matchMedia('(max-width: 700px)').matches
  return lowMemory || lowConcurrency || compactViewport ? 'lite' : 'full'
}

export function useMotionProfile() {
  const [profile, setProfile] = useState<MotionProfile>(() => detectMotionProfile())

  useEffect(() => {
    const reducedQuery = window.matchMedia('(prefers-reduced-motion: reduce)')
    const compactQuery = window.matchMedia('(max-width: 700px)')
    const update = () => setProfile(detectMotionProfile())
    reducedQuery.addEventListener('change', update)
    compactQuery.addEventListener('change', update)
    return () => {
      reducedQuery.removeEventListener('change', update)
      compactQuery.removeEventListener('change', update)
    }
  }, [])

  return profile
}
