import { useEffect, useMemo, useRef, useState } from 'react'
import type { RouteKey } from '../App'
import type { KnowledgeEntry } from '../data/qianling-knowledge'
import { MascotDialogue } from './qianling/MascotDialogue'
import { useMascotAnimation } from './qianling/MascotAnimation'
import { useMascotGuideController } from './qianling/MascotGuideController'
import { QianlingMascot } from './qianling/QianlingMascot'
import { buildGuideMessage } from './qianling/guideMessages'
import { useDraggablePet } from './qianling/useDraggablePet'

const routeGreetings: Record<RouteKey, string> = {
  prologue: '选择空气、水或森林，生态核心会同步切换。',
  atlas: '点击地图或城市列表，可联动查看城市空气数据。',
  time: '点亮年份回溯档案，也可以切换城市查看趋势。',
  symbiosis: '切换水与森林指标，点我了解统计口径。',
  story: '向下滚动阅读长卷，右侧刻度可以跳转章节。',
}

export function EcoGuide({ route }: { route: RouteKey }) {
  const guideRef = useRef<HTMLElement>(null)
  const { pageContext, announcementId } = useMascotGuideController()
  const { state, play } = useMascotAnimation('idle')
  const pet = useDraggablePet(guideRef)
  const [open, setOpen] = useState(false)
  const [minimized, setMinimized] = useState(false)
  const [showGreetingBubble, setShowGreetingBubble] = useState(false)
  const [activeKnowledge, setActiveKnowledge] = useState<KnowledgeEntry | null>(null)
  const message = useMemo(() => buildGuideMessage(route, pageContext), [route, pageContext])

  useEffect(() => {
    setActiveKnowledge(null)
    const greetingKey = `qianjing-qianling-greeted-${route}-v1`
    if (!window.sessionStorage.getItem(greetingKey)) {
      window.sessionStorage.setItem(greetingKey, '1')
      setOpen(false)
      setShowGreetingBubble(true)
      play('greeting', 2600)
      const greetingTimer = window.setTimeout(() => setShowGreetingBubble(false), 4800)
      return () => window.clearTimeout(greetingTimer)
    }
    setShowGreetingBubble(false)
    setOpen(false)
    play(route === 'story' || route === 'symbiosis' ? 'guiding' : 'idle', 1400)
  }, [route, play])

  useEffect(() => {
    if (!announcementId) return
    setMinimized(false)
    setShowGreetingBubble(false)
    setOpen(true)
    setActiveKnowledge(null)
    play('guiding', 2600)
  }, [announcementId, play])

  useEffect(() => {
    if (route !== pageContext.route) return
    if (route === 'story' || route === 'symbiosis') play('guiding', 1500)
  }, [pageContext, route, play])

  useEffect(() => {
    if (!pet.dragging) return
    play('guiding')
  }, [pet.dragging, play])

  useEffect(() => {
    if (open || pet.dragging || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
    const timer = window.setTimeout(() => play('hover', 1500), 7000 + Math.round(Math.random() * 5000))
    return () => window.clearTimeout(timer)
  }, [open, pet.dragging, play, route])

  useEffect(() => {
    let frame = 0
    const followPointer = (event: PointerEvent) => {
      if (document.body.dataset.motion === 'reduced') return
      if (frame) window.cancelAnimationFrame(frame)
      frame = window.requestAnimationFrame(() => {
        const avatar = guideRef.current?.querySelector<HTMLElement>('.qianling-avatar')
        const mascot = guideRef.current?.querySelector<SVGSVGElement>('.qianling-mascot')
        if (!avatar || !mascot) return
        const rect = avatar.getBoundingClientRect()
        const x = Math.max(-2.4, Math.min(2.4, (event.clientX - (rect.left + rect.width / 2)) / 36))
        const y = Math.max(-1.7, Math.min(1.7, (event.clientY - (rect.top + rect.height * .42)) / 42))
        mascot.style.setProperty('--look-x', `${x}px`)
        mascot.style.setProperty('--look-y', `${y}px`)
      })
    }
    window.addEventListener('pointermove', followPointer, { passive: true })
    return () => {
      window.removeEventListener('pointermove', followPointer)
      if (frame) window.cancelAnimationFrame(frame)
    }
  }, [])

  useEffect(() => {
    if (route !== 'prologue') return
    const frame = window.requestAnimationFrame(() => {
      const guideRect = guideRef.current?.getBoundingClientRect()
      const readoutRect = document.querySelector<HTMLElement>('.triad-signal-readout')?.getBoundingClientRect()
      if (!guideRect || !readoutRect) return
      const overlapsReadout = guideRect.left < readoutRect.right
        && guideRect.right > readoutRect.left
        && guideRect.top < readoutRect.bottom
        && guideRect.bottom > readoutRect.top
      if (overlapsReadout) pet.resetPosition()
    })
    return () => window.cancelAnimationFrame(frame)
  }, [pet.resetPosition, route])

  const toggle = () => {
    setShowGreetingBubble(false)
    if (open) {
      setOpen(false)
      setActiveKnowledge(null)
      play('idle')
    } else {
      setOpen(true)
      play('talking')
    }
  }

  if (minimized) return (
    <button type="button" className={`qianling-restore qianling-restore-${route}`} data-guide-target="mascot" onClick={() => { setMinimized(false); play('greeting', 1800) }}>
      <span>唤回黔小灵</span><i />
    </button>
  )

  return (
    <aside
      ref={guideRef}
      className={`eco-guide eco-guide-${route} ${open ? 'is-open' : ''} is-${pet.edge}-edge ${pet.dragging ? 'is-dragging' : ''} ${pet.snapping ? 'is-snapping' : ''}`}
      data-guide-target="mascot"
      style={pet.style}
      aria-label="黔小灵生态向导"
    >
      {showGreetingBubble && <p className="qianling-greeting-bubble"><strong>{route === 'prologue' ? '你好，我是黔小灵！' : `本章提示 · ${route === 'atlas' ? '黔境图谱' : route === 'time' ? '时光实验室' : route === 'symbiosis' ? '山水共生' : '生态长卷'}`}</strong><span>{routeGreetings[route]}</span></p>}
      {open && (
        <MascotDialogue
          message={message}
          activeKnowledge={activeKnowledge}
          onKnowledge={(entry) => { setActiveKnowledge(entry); play('talking') }}
          onBack={() => { setActiveKnowledge(null); play('talking', 1200) }}
          onClose={() => { setOpen(false); setActiveKnowledge(null); play('idle') }}
          onHide={() => { setOpen(false); setMinimized(true); setActiveKnowledge(null); play('idle') }}
          onResetPosition={() => { pet.resetPosition(); play('greeting', 1400) }}
        />
      )}
      <button
        type="button"
        className="qianling-avatar"
        aria-expanded={open}
        aria-controls="qianling-dialogue"
        aria-label={open ? '收起黔小灵' : '打开黔小灵生态向导'}
        aria-description="可以拖动黔小灵到屏幕安全位置，也可使用方向键移动，按住 Shift 可加速。"
        onClick={() => { if (!pet.consumeSuppressedClick()) toggle() }}
        onKeyDown={(event) => { if (pet.moveByKeyboard(event)) play('guiding', 900) }}
        onMouseEnter={() => play('hover')}
        onMouseLeave={() => play(open ? 'talking' : 'idle')}
        onFocus={() => play('hover')}
        onBlur={() => play(open ? 'talking' : 'idle')}
        {...pet.pointerHandlers}
      >
        <QianlingMascot state={state} route={route} />
        <span><i /> 黔小灵</span>
      </button>
      <span className="qianling-drag-hint" aria-hidden="true">DRAG · 拖动我</span>
    </aside>
  )
}
