import { useState, type KeyboardEvent, type PointerEvent } from 'react'
import { metricLabel, type AirMetric, type CityKey, type TemporalResolution } from '../data/ecology'

interface BeforeAfterMirrorProps {
  leftLabel: string
  rightLabel: string
  leftValue: number | null
  rightValue: number | null
  city: CityKey
  metric: AirMetric
  divider: number
  delta: number | null
  percent: number | null
  isYearOnYear: boolean
  temporalResolution?: TemporalResolution
  onDividerChange: (value: number) => void
}

const clampDivider = (value: number) => Math.min(92, Math.max(8, value))

export function BeforeAfterMirror({
  leftLabel, rightLabel, leftValue, rightValue, city, metric, divider, delta, percent, isYearOnYear, temporalResolution = 'month', onDividerChange,
}: BeforeAfterMirrorProps) {
  const [dragging, setDragging] = useState(false)

  const setFromPointer = (event: PointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect()
    onDividerChange(clampDivider((event.clientX - rect.left) / rect.width * 100))
  }

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerType === 'mouse' && event.button !== 0) return
    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    setDragging(true)
    setFromPointer(event)
  }

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (dragging) setFromPointer(event)
  }

  const stopDragging = (event: PointerEvent<HTMLDivElement>) => {
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId)
    setDragging(false)
  }

  const onDividerKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const step = event.shiftKey ? 5 : 1
    let next = divider
    if (event.key === 'ArrowRight' || event.key === 'ArrowUp') next += step
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') next -= step
    else if (event.key === 'Home') next = 8
    else if (event.key === 'End') next = 92
    else return
    event.preventDefault()
    onDividerChange(clampDivider(next))
  }

  return (
    <>
      <div
        className={`compare-mirror ${dragging ? 'is-dragging' : ''}`}
        data-guide-target="time-comparison"
        data-change={delta === null ? 'missing' : delta <= 0 ? 'down' : 'up'}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={stopDragging}
        onPointerCancel={stopDragging}
      >
        <div className="compare-side compare-left">
          <span>{leftLabel}</span><strong>{leftValue ?? '—'}</strong><small>{city} · {metricLabel[metric]} μg/m³</small>
        </div>
        <div className="compare-side compare-right" style={{ clipPath: `inset(0 0 0 ${divider}%)` }}>
          <span>{rightLabel}</span><strong>{rightValue ?? '—'}</strong><small>{city} · {metricLabel[metric]} μg/m³</small>
        </div>
        <button
          type="button"
          className="compare-divider"
          style={{ left: `${divider}%` }}
          role="slider"
          aria-label="拖动双时刻对照分割线"
          aria-valuemin={8}
          aria-valuemax={92}
          aria-valuenow={Math.round(divider)}
          aria-valuetext={`左侧显示${Math.round(divider)}%，右侧显示${Math.round(100 - divider)}%`}
          onKeyDown={onDividerKeyDown}
        ><i /><span>拖动</span></button>
        <div className="compare-mountains" aria-hidden="true"><i /><i /><i /></div>
        <p className="mirror-disclaimer">抽象数据景观 · 非遥感或监测影像</p>
      </div>
      <label className="divider-control">
        <span className="sr-only">调整双时刻对照分割线</span>
        <input type="range" min="8" max="92" value={divider} onChange={(event) => onDividerChange(Number(event.target.value))} />
      </label>
      <div className="comparison-result" aria-live="polite">
        <span>{rightLabel} 相比 {leftLabel}</span>
        <strong className={(delta ?? 0) <= 0 ? 'is-down' : 'is-up'}>{delta === null ? '暂无数据' : `${delta > 0 ? '+' : ''}${delta} μg/m³`}</strong>
        <span>{percent === null ? '—' : `${percent > 0 ? '+' : ''}${percent.toFixed(1)}%`}</span>
        {temporalResolution === 'year'
          ? <small>同一城市年度均值对照；仅在官方口径一致时开放。</small>
          : isYearOnYear ? <small>同月同比，可直接观察该指标变化。</small> : <small>月份不同，变化可能包含季节因素，请谨慎解释。</small>}
      </div>
    </>
  )
}
