import { useId, useMemo, useState, type CSSProperties } from 'react'
import type { AirCityRecord, AirMetric, CityKey } from '../data/ecology'
import { metricLabel } from '../data/ecology'

export interface EcoTrendDatum {
  id: string
  label: string
  value: number | null
}

const timeValue = (id: string, index: number) => {
  const match = /^(\d{4})-(\d{2})$/.exec(id)
  const year = /^(\d{4})$/.exec(id)
  return match ? Date.UTC(Number(match[1]), Number(match[2]) - 1, 1) : year ? Date.UTC(Number(year[1]), 0, 1) : index
}

export function HistoricalSignalTrace({ data, unit, activeId, ariaLabel }: {
  data: EcoTrendDatum[]
  unit: string
  activeId?: string
  ariaLabel: string
}) {
  const gradientId = `eco-trace-${useId().replace(/:/g, '')}`
  const [hoveredId, setHoveredId] = useState<string | null>(null)
  const valid = useMemo(() => data.filter((item): item is EcoTrendDatum & { value: number } => item.value !== null), [data])
  const min = valid.length ? Math.min(...valid.map((item) => item.value)) : 0
  const max = valid.length ? Math.max(...valid.map((item) => item.value)) : 1
  const times = valid.map((item, index) => timeValue(item.id, index))
  const minTime = times.length ? Math.min(...times) : 0
  const maxTime = times.length ? Math.max(...times) : 1
  const points = valid.map((item, index) => ({
    ...item,
    x: 22 + ((times[index] - minTime) / Math.max(1, maxTime - minTime)) * 206,
    y: 70 - ((item.value - min) / Math.max(1, max - min)) * 50,
  }))
  const pointString = points.map((item) => `${item.x},${item.y}`).join(' ')
  const active = points.find((item) => item.id === (hoveredId ?? activeId)) ?? points[points.length - 1]

  if (!points.length) return <div className="eco-hud-empty"><i />暂无可核验节点</div>

  return (
    <div className="eco-signal-trace">
      <svg viewBox="0 0 240 104" role="img" aria-label={ariaLabel}>
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#F5DC91" stopOpacity=".3" />
            <stop offset="1" stopColor="#D9C27A" stopOpacity="0" />
          </linearGradient>
        </defs>
        <g className="eco-trace-grid" aria-hidden="true">
          {[20, 36.6, 53.3, 70].map((y) => <line key={y} x1="22" x2="228" y1={y} y2={y} />)}
          {points.map((item) => <line key={item.id} x1={item.x} x2={item.x} y1="18" y2="72" />)}
        </g>
        <polygon className="eco-trace-area" points={`${pointString} ${points[points.length - 1].x},72 ${points[0].x},72`} fill={`url(#${gradientId})`} />
        <polyline className="eco-trace-line" points={pointString} />
        {active && <g className="eco-trace-crosshair" aria-hidden="true"><line x1={active.x} x2={active.x} y1="15" y2="75" /><line x1="20" x2="230" y1={active.y} y2={active.y} /></g>}
        {points.map((item) => (
          <g
            key={item.id}
            className={`eco-trace-node ${item.id === (hoveredId ?? activeId) ? 'is-active' : ''}`}
            role="button"
            tabIndex={0}
            aria-label={`${item.label}：${item.value}${unit}`}
            onMouseEnter={() => setHoveredId(item.id)}
            onMouseLeave={() => setHoveredId(null)}
            onFocus={() => setHoveredId(item.id)}
            onBlur={() => setHoveredId(null)}
          >
            <circle cx={item.x} cy={item.y} r="7" className="eco-trace-hit" />
            <circle cx={item.x} cy={item.y} r="2.8" />
            <text x={item.x} y="91" textAnchor="middle">{item.label}</text>
          </g>
        ))}
      </svg>
      <output className="eco-trace-tooltip" aria-live="polite">
        <span>{active.label}</span><strong>{active.value}</strong><small>{unit}</small>
      </output>
      <p>仅连接已获取观测节点 · 横轴按实际时间间隔定位</p>
    </div>
  )
}

export function CityBeaconMatrix({ records, metric, selected, onSelect }: {
  records: AirCityRecord[]
  metric: AirMetric
  selected: CityKey
  onSelect: (city: CityKey) => void
}) {
  const max = Math.max(...records.map((item) => item[metric]), 1)
  const scaleMax = Math.ceil(max / 10) * 10

  return (
    <div className="eco-city-beacons" aria-label={`${metricLabel[metric]}九城市信标`}>
      <div className="eco-beacon-scale" aria-hidden="true"><span>0</span><i /><span>{scaleMax} μg/m³</span></div>
      <div className="eco-beacon-grid">
        {records.map((record, index) => (
          <button
            type="button"
            key={record.city}
            className={record.city === selected ? 'is-active' : ''}
            onClick={() => onSelect(record.city)}
            style={{ '--signal': `${record[metric] / scaleMax * 100}%` } as CSSProperties}
            aria-label={`${record.city} ${metricLabel[metric]} ${record[metric]}微克每立方米`}
          >
            <span>{String(index + 1).padStart(2, '0')}</span>
            <b>{record.city.replace('市', '')}</b>
            <i><em /></i>
            <strong>{record[metric]}</strong>
          </button>
        ))}
      </div>
    </div>
  )
}

export function MicroDataSpectrum({ records, metric, selected, onSelect, frequencyLabel = '月均' }: {
  records: AirCityRecord[]
  metric: AirMetric
  selected: CityKey
  onSelect: (city: CityKey) => void
  frequencyLabel?: '月均' | '年均'
}) {
  const max = Math.max(...records.map((item) => item[metric]), 1)
  return (
    <div className="eco-micro-spectrum">
      <header><span>MICRO DATA SPECTRUM</span><strong>09 VERIFIED CITY NODES</strong></header>
      <div className="eco-spectrum-grid" role="list" aria-label={`${metricLabel[metric]}九城市真实值微型频谱`}>
        {records.map((record, index) => (
          <button
            type="button"
            role="listitem"
            key={record.city}
            className={record.city === selected ? 'is-active' : ''}
            onClick={() => onSelect(record.city)}
            aria-label={`${record.city} ${record[metric]}微克每立方米`}
          >
            <i style={{ height: `${Math.max(8, record[metric] / max * 100)}%` }}><em /></i>
            <span>{String(index + 1).padStart(2, '0')}</span>
          </button>
        ))}
      </div>
      <footer><span>{metricLabel[metric]} · μg/m³</span><span>真实城市{frequencyLabel}值 · 非装饰随机信号</span></footer>
    </div>
  )
}
