import { lazy, Suspense } from 'react'
import type { ParticleTerrainSceneProps } from './ParticleTerrainScene'

const ParticleTerrainScene = lazy(() => import('./ParticleTerrainScene').then((module) => ({ default: module.ParticleTerrainScene })))

export function LazyParticleTerrainScene(props: ParticleTerrainSceneProps) {
  return (
    <Suspense fallback={(
      <div className="particle-terrain-scene particle-is-loading" role="status" aria-label="粒子生态地形正在载入">
        <div className="particle-terrain-fallback" aria-hidden="true"><i /><i /><i /></div>
        <p className="particle-loading-label"><span /> INITIALIZING PARTICLE TERRAIN</p>
      </div>
    )}>
      <ParticleTerrainScene {...props} />
    </Suspense>
  )
}
