import { useState, type RefObject } from 'react'
import { toPng } from 'html-to-image'

interface ChartExportButtonProps {
  targetRef: RefObject<HTMLElement>
  filename: string
  backgroundColor?: string
}

export function ChartExportButton({ targetRef, filename, backgroundColor = '#0C2421' }: ChartExportButtonProps) {
  const [exporting, setExporting] = useState(false)
  const [error, setError] = useState('')

  const exportPng = async () => {
    if (!targetRef.current || exporting) return
    setExporting(true)
    setError('')
    try {
      const dataUrl = await toPng(targetRef.current, {
        cacheBust: true,
        pixelRatio: 2,
        backgroundColor,
        filter: (node) => !(node instanceof HTMLElement && node.dataset.exportIgnore === 'true'),
      })
      const link = document.createElement('a')
      link.download = `${filename}.png`
      link.href = dataUrl
      link.click()
    } catch (reason) {
      console.error('Chart export failed', reason)
      setError('导出失败，请重试')
    } finally {
      setExporting(false)
    }
  }

  return (
    <span className="chart-export-wrap" data-export-ignore="true">
      <button type="button" className="chart-export-button" onClick={exportPng} disabled={exporting}>
        {exporting ? '正在生成…' : '导出 PNG ↗'}
      </button>
      {error && <small role="status">{error}</small>}
    </span>
  )
}
