import { useEffect, useMemo, useRef, useState } from 'react'
import { SourcePanel } from '../components/SourcePanel'
import { ContourField } from '../components/ContourField'
import { ChartExportButton } from '../components/ChartExportButton'
import { HistoricalSignalTrace } from '../components/EcoHudCharts'
import { forestAnnual, forestRestoration, waterAnnual } from '../data/ecology'
import forestScene from '../assets/forest-cinematic.jpg'
import waterScene from '../assets/water-cinematic.jpg'
import { useMascotGuideController } from '../components/qianling/MascotGuideController'

type WaterMetric = 'main_river_class_i_iii_rate' | 'surface_water_provincial_class_i_iii_rate'
type ForestMetric = 'afforestation_area' | 'forest_coverage_rate'

const waterMetricLabel: Record<WaterMetric, string> = {
  main_river_class_i_iii_rate: '主要河流Ⅰ—Ⅲ类断面比例',
  surface_water_provincial_class_i_iii_rate: '省控地表水Ⅰ—Ⅲ类断面比例',
}

const forestMetricLabel: Record<ForestMetric, string> = {
  afforestation_area: '年度完成营造林面积',
  forest_coverage_rate: '森林覆盖率',
}

export function Symbiosis() {
  const waterChartRef = useRef<HTMLDivElement>(null)
  const forestChartRef = useRef<HTMLDivElement>(null)
  const waterSectionRef = useRef<HTMLElement>(null)
  const forestSectionRef = useRef<HTMLElement>(null)
  const [waterMetric, setWaterMetric] = useState<WaterMetric>('main_river_class_i_iii_rate')
  const [forestMetric, setForestMetric] = useState<ForestMetric>('afforestation_area')
  const { publishPageContext } = useMascotGuideController()

  const waterSeries = useMemo(() => waterAnnual
    .filter((item) => item.indicator === waterMetric)
    .sort((a, b) => a.year - b.year), [waterMetric])
  const forestSeries = useMemo(() => forestAnnual
    .filter((item) => item.indicator === forestMetric)
    .sort((a, b) => a.year - b.year), [forestMetric])
  const forestTrace = forestSeries.map((item) => ({
    id: String(item.year),
    label: String(item.year),
    value: forestMetric === 'forest_coverage_rate' && item.year === 2025 ? null : item.value,
  }))
  const latestWater = [...waterSeries].reverse().find((item) => item.value !== null)
  const mainRiverSegments = [
    { label: '2016—2020 · 79条河流 / 151断面', records: waterSeries.filter((item) => item.year <= 2020) },
    { label: '2021—2024 · 222个省控断面', records: waterSeries.filter((item) => item.year >= 2021) },
  ]
  const latestForest = forestSeries[forestSeries.length - 1]
  const forest2025Coverage = forestAnnual.find((item) => item.year === 2025 && item.indicator === 'forest_coverage_rate')
  const sourceIds = Array.from(new Set([...waterAnnual, ...forestAnnual].flatMap((item) => item.sourceIds)))

  useEffect(() => {
    const requestedSection = new URLSearchParams(window.location.hash.split('?')[1] ?? '').get('section')
    publishPageContext({ route: 'symbiosis', section: requestedSection === 'forest' ? 'forest' : 'water' })
    const requestedTarget = requestedSection === 'forest' ? forestSectionRef.current : requestedSection === 'water' ? waterSectionRef.current : null
    let focusFrame = 0
    if (requestedTarget) {
      focusFrame = window.requestAnimationFrame(() => requestedTarget.scrollIntoView({
        behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
        block: 'start',
      }))
    }
    const observer = new IntersectionObserver((entries) => {
      const visible = entries.filter((entry) => entry.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0]
      if (!visible) return
      publishPageContext({ route: 'symbiosis', section: visible.target === forestSectionRef.current ? 'forest' : 'water' })
    }, { rootMargin: '-28% 0px -38% 0px', threshold: [0, .2, .5] })
    if (waterSectionRef.current) observer.observe(waterSectionRef.current)
    if (forestSectionRef.current) observer.observe(forestSectionRef.current)
    return () => {
      observer.disconnect()
      if (focusFrame) window.cancelAnimationFrame(focusFrame)
    }
  }, [publishPageContext])

  return (
    <div className="page symbiosis-page">
      <ContourField variant="ink" className="symbiosis-contours" label="WATER × FOREST / 2016—2025 ANNUAL ARCHIVE" />
      <header className="page-hero paper-hero">
        <div><p className="eyebrow"><span>04</span> IMMERSIVE NATURAL ARCHIVE · SYMBIOSIS</p><h1>一滴水穿过山脉，<br />一片林记录年份。</h1></div>
        <p>2016—2025省级年度档案已经接入。水环境在2021年发生断面网络变化，森林覆盖率在2025年切换普查口径；页面明确保留这些断点。</p>
      </header>

      <section className="water-section" id="water" ref={waterSectionRef}>
        <div className="immersive-scene-media water-visual">
          <img src={waterScene} alt="原创贵州灵感喀斯特山地河流艺术场景，非监测影像" />
          <svg viewBox="0 0 900 480">
            <defs><linearGradient id="stream" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#86BFCF" /><stop offset="1" stopColor="#83C8AB" /></linearGradient></defs>
            <path d="M28 90C180 20 268 194 405 116S596 80 866 26" />
            <path d="M-20 265C164 166 282 352 430 247S659 187 925 282" />
            <path d="M26 430C208 330 364 452 505 356S708 328 895 391" />
            <circle cx="405" cy="116" r="70" />
            <circle cx="430" cy="247" r="112" />
            <circle cx="505" cy="356" r="48" />
          </svg>
          <div className="scene-scanline" aria-hidden="true" />
          <p><span>WATER SENSOR FIELD</span><strong>{latestWater?.value ?? '—'}%</strong><small>{latestWater?.year ?? '—'} · 官方年度档案</small></p>
        </div>
        <div className="water-copy" data-guide-target="symbiosis-water">
          <p className="eyebrow">01 / RIVER ARCHIVE</p>
          <h2>江河之脉</h2>
          <p>“优良”对应特定断面网络和评价标准。切换指标时，页面只连接同一统计范围内的年度节点。</p>
          <div className="annual-metric-switch" aria-label="选择水环境年度指标">
            {(Object.keys(waterMetricLabel) as WaterMetric[]).map((key) => <button type="button" key={key} className={waterMetric === key ? 'is-active' : ''} onClick={() => setWaterMetric(key)}>{waterMetricLabel[key]}</button>)}
          </div>
          <ChartExportButton targetRef={waterChartRef} filename={`黔境-${waterMetricLabel[waterMetric]}`} backgroundColor="#07120f" />
        <div className="annual-archive-chart water-annual-chart" ref={waterChartRef} data-guide-target="symbiosis-water">
            <header className="water-hud-title"><span>04</span><div><strong>{waterMetricLabel[waterMetric]}</strong><small>2016—2025 · PROVINCIAL ANNUAL ARCHIVE</small></div><i /></header>
            {waterMetric === 'main_river_class_i_iii_rate' ? (
              <div className="method-split-traces" aria-label="主要河流断面两种统计口径的分段序列">
                {mainRiverSegments.map((segment) => (
                  <section key={segment.label}>
                    <small>{segment.label}</small>
                    <HistoricalSignalTrace data={segment.records.map((item) => ({ id: String(item.year), label: String(item.year), value: item.value }))} unit="%" activeId={String(segment.records[segment.records.length - 1]?.year ?? '')} ariaLabel={`${segment.label}年度序列`} />
                  </section>
                ))}
              </div>
            ) : (
              <HistoricalSignalTrace data={waterSeries.map((item) => ({ id: String(item.year), label: String(item.year), value: item.value }))} unit="%" activeId={String(latestWater?.year ?? '')} ariaLabel={`${waterMetricLabel[waterMetric]}年度序列`} />
            )}
            <div className="archive-latest-reading"><span>LATEST VERIFIED</span><strong>{latestWater?.value ?? '—'}<i>%</i></strong><small>{latestWater?.year ?? '—'} · {latestWater?.scope ?? '暂无同口径数据'}</small></div>
          </div>
          <p className="scope-warning dark-warning">口径提示：2016—2020主要河流为79条河流151个断面；2021年起采用222个主要河流省控断面。两段序列不直接计算跨口径增减。2025年未单列222断面值，保持缺失。</p>
        </div>
      </section>

      <section className="forest-section" id="forest" ref={forestSectionRef}>
        <div className="forest-backdrop"><img src={forestScene} alt="原创贵州灵感山地森林艺术场景，非遥感影像" /><div className="scene-scanline" aria-hidden="true" /></div>
        <div className="forest-copy" data-guide-target="symbiosis-forest">
          <p className="eyebrow">02 / FOREST ARCHIVE</p>
          <h2>青山之境</h2>
          <p>营造林面积是年度完成量，森林覆盖率是资源状态比例，两者不能互相替代。</p>
          <div className="forest-number"><strong>{latestForest?.value ?? '—'}</strong><span>{latestForest?.unit}<br />{latestForest?.year}年 · {forestMetricLabel[forestMetric]}</span></div>
          <div className="annual-metric-switch forest-metric-switch" aria-label="选择森林年度指标">
            {(Object.keys(forestMetricLabel) as ForestMetric[]).map((key) => <button type="button" key={key} className={forestMetric === key ? 'is-active' : ''} onClick={() => setForestMetric(key)}>{forestMetricLabel[key]}</button>)}
          </div>
          {forestMetric === 'forest_coverage_rate' && <p className="forest-extra">2025年官方值为 <strong>{forest2025Coverage?.value}%</strong>，但采用2024年度森林草原湿地荒漠化普查新口径，因此作为独立档案显示，不与2016—2024折线相连。</p>}
          {forestRestoration && <p className="forest-extra">另有2025年石漠化综合治理 <strong>{forestRestoration.value} {forestRestoration.unit}</strong>，不与森林覆盖率或营造林面积合并。</p>}
          <ChartExportButton targetRef={forestChartRef} filename={`黔境-${forestMetricLabel[forestMetric]}`} backgroundColor="#07100a" />
        </div>
        <div className="forest-chart annual-forest-chart" role="img" aria-label={`${forestMetricLabel[forestMetric]}2016至2025年度趋势`} ref={forestChartRef} data-guide-target="symbiosis-forest">
          <header className="forest-hud-title"><span>05</span><div><strong>{forestMetricLabel[forestMetric]}</strong><small>ANNUAL FOREST ARCHIVE · VERIFIED DATA ONLY</small></div><i /></header>
          <div className="contour-lines" aria-hidden="true">{Array.from({ length: 7 }, (_, i) => <i key={i} />)}</div>
          <div className="forest-trend-shell">
            <HistoricalSignalTrace data={forestTrace} unit={latestForest?.unit ?? ''} activeId={forestMetric === 'forest_coverage_rate' ? '2024' : '2025'} ariaLabel={`${forestMetricLabel[forestMetric]}年度序列`} />
            <div className="forest-year-grid" aria-label="十年官方数值">
              {forestSeries.map((item) => <span key={item.year} className={forestMetric === 'forest_coverage_rate' && item.year === 2025 ? 'is-method-break' : ''}><i>{item.year}</i><strong>{item.value}</strong><small>{item.unit}</small></span>)}
            </div>
          </div>
          <p>{forestMetric === 'forest_coverage_rate' ? '2025 METHOD BREAK / 新普查口径独立显示' : 'ANNUAL AFFORESTATION COMPLETED AREA / 年度完成量'}</p>
        </div>
      </section>
      <SourcePanel sourceIds={sourceIds} />
    </div>
  )
}
